 38	/// Resolve one local linear/radial paint template, then rebind instance inverse
 39	/// and edge bounds. The returned template witness lets the scene builder share
 40	/// graph stop storage across fills and strokes in that scene.
 41	pub fn resolve_fill(
 42	    ctx: &mut ResolveContext<'_, '_>,
 43	    value: XmlSpan,
 44	    edges: &[Edge],
 45	    user_inverse: Affine,
 46	    viewport: [f64; 2],
 47	    work: &mut dyn WorkControl,
 48	) -> Result<ResolvedPaint> {
 49	    let cached = resolve_cached_fill(
 50	        ctx.shared,
 51	        ctx.cache,
 52	        ctx.ledger,
 53	        value,
 54	        edges,
 55	        user_inverse,
 56	        viewport,
 57	        work,
 58	    )?;
 59	    // This compatibility interface is explicitly owned, not a cache handoff.
 60	    Ok(cached.to_owned(ctx.ledger, work)?.into_job_owned())
 61	}
