 63	/// Resolve a template and borrow its actual cache storage. Only `cache` is
 64	/// borrowed by the result; source/context/ledger/control borrows end on return.
 65	/// Publish through CachedPaint::append_fill/append_stroke without stop copies.
 66	pub fn resolve_cached_fill<'cache>(
 67	    shared: &mut DecodeSource<'_>,
 68	    cache: &'cache mut PaintCache,
 69	    ledger: &mut ChargeLedger,
 70	    value: XmlSpan,
 71	    edges: &[Edge],
 72	    user_inverse: Affine,
 73	    viewport: [f64; 2],
 74	    work: &mut dyn WorkControl,
 75	) -> Result<CachedPaint<'cache>> {
 76	    if !Arc::ptr_eq(shared.source_owner(), ledger.source_owner())
 77	        || cache
 78	            .entries
 79	            .first()
 80	            .is_some_and(|entry| !Arc::ptr_eq(&entry.source, shared.source_owner()))
 81	    {
 82	        return Err(invalid(value.offset));
 83	    }
 84	    let result = {
 85	        let mut control = PaintControl::new(ledger, work);
 86	        let result = resolve_inner(
 87	            shared,
 88	            cache,
 89	            value,
 90	            edges,
 91	            user_inverse,
 92	            viewport,
 93	            &mut control,
 94	        );
 95	        control.result_at(result, value.offset)?
 96	    };
 97	    let entry = cache
 98	        .entries
 99	        .get(result.index)
100	        .ok_or_else(|| invalid(value.offset))?;
101	    Ok(CachedPaint::new(
102	        result.paint,
103	        result.template,
104	        &entry.stops,
105	        &entry.source,
106	        value.offset,
107	    ))
108	}
