110	/// Consume a temporary borrowed-flow context while preserving only its cache
111	/// borrow in the result. Shared source, ledger and control remain reusable.
112	pub fn resolve_cached_context<'src, 'cache>(
113	    ctx: CachedResolveContext<'src, 'cache, '_>,
114	    value: XmlSpan,
115	    edges: &[Edge],
116	    user_inverse: Affine,
117	    viewport: [f64; 2],
118	    work: &mut dyn WorkControl,
119	) -> Result<CachedPaint<'cache>> {
120	    resolve_cached_fill(
121	        ctx.shared,
122	        ctx.cache,
123	        ctx.ledger,
124	        value,
125	        edges,
126	        user_inverse,
127	        viewport,
128	        work,
