177	fn resolve_inner(
178	    shared: &mut DecodeSource<'_>,
179	    cache: &mut vexel_scene::PaintCache,
180	    value: XmlSpan,
181	    edges: &[Edge],
182	    user_inverse: Affine,
183	    viewport: [f64; 2],
184	    control: &mut PaintControl<'_>,
185	) -> Result<TemplateResolution> {
186	    control
187	        .checkpoint()
188	        .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
189	    let reference = classify_inner(shared, value, control)?;
190	    let PaintReference::Gradient(target) = reference else {
191	        return Err(unsupported(value.offset));
192	    };
193	    let target_token = shared
194	        .tokens()
195	        .get(target.0)
196	        .ok_or_else(|| invalid(value.offset))?;
197	    let linear = eq(shared.source(), target_token.local_name, b"linearGradient");
198	    let template_id = shared
199	        .gradient_template_id(target, viewport, control)
200	        .map_err(|error| remap(error, value.offset))?;
201	    let source_owner = Arc::clone(shared.source_owner());
202	
203	    if let Some(index) = cache::find_template(
204	        cache,
205	        &source_owner,
206	        target,
207	        viewport,
208	        if linear {
209	            PaintKind::Linear
210	        } else {
211	            PaintKind::Radial
212	        },
213	        control,
214	        value.offset,
215	    )? {
216	        let paint = bind_instance(
217	            cache.entries[index].paint,
218	            edges,
219	            user_inverse,
220	            value.offset,
221	            control,
222	        )?;
223	        control
224	            .checkpoint()
225	            .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
226	        return Ok(TemplateResolution {
227	            index,
228	            paint,
229	            template: template_id,
230	        });
231	    }
232	
233	    let mut chain = [ElementId(0); 16];
234	    let chain_count = collect_chain(
235	        shared,
236	        target,
237	        linear,
238	        &mut chain,
239	        cache,
240	        control,
241	        value.offset,
242	    )?;
243	    let kind = if linear {
244	        PaintKind::Linear
245	    } else {
246	        PaintKind::Radial
247	    };
248	    let mut definition = Paint {
249	        kind,
250	        spread: Spread::Pad,
251	        object_bounding_box: true,
252	        coordinates: [0.0; 6],
253	        bounds: [0.0; 4],
254	        user_inverse: affine_identity(),
255	        gradient_inverse: affine_identity(),
256	        stops: TableRange::EMPTY,
257	        pattern: None,
258	        pattern_inverse: affine_identity(),
259	        pattern_opacity: 1.0,
260	    };
261	    gradient_data::read_definition_attributes(
262	        shared.source(),
263	        shared.tokens(),
264	        &chain[..chain_count],
265	        &mut definition,
266	        value.offset,
267	    )?;
268	    gradient_data::read_coordinates(
269	        shared.source(),
270	        shared.tokens(),
271	        &chain[..chain_count],
272	        viewport,
273	        &mut definition,
274	        value.offset,
275	    )?;
276	    let (mut stops, stop_count, stop_lease) =
277	        gradient_data::collect_stops(shared, &chain[..chain_count], cache, control, value.offset)?;
278	    if stop_count < 2 {
279	        control.ledger.release(stop_lease)?;
280	        return Err(unsupported(value.offset));
281	    }
282	    stops.truncate(stop_count);
283	    definition.stops = TableRange {
284	        first: 0,
285	        count: stop_count,
286	    };
287	    let template_paint = definition;
288	    if control.checkpoint().is_err() {
289	        control.ledger.release(stop_lease)?;
290	        return Err(limit(vexel_scene::LimitKind::Work, value.offset));
291	    }
292	    let index = cache::insert_template(
293	        cache,
294	        &source_owner,
295	        target,
296	        viewport,
297	        template_paint,
298	        stops,
299	        stop_lease,
300	        control,
301	        value.offset,
302	    )?;
303	    let mut instance = bind_instance(template_paint, edges, user_inverse, value.offset, control)?;
304	    instance.stops = template_paint.stops;
305	    Ok(TemplateResolution {
306	        index,
307	        paint: instance,
308	        template: template_id,
309	    })
310	}
