344	fn collect_chain(
345	    shared: &mut DecodeSource<'_>,
346	    target: ElementId,
347	    linear: bool,
348	    chain: &mut [ElementId; 16],
349	    cache: &mut vexel_scene::PaintCache,
350	    control: &mut PaintControl<'_>,
351	    offset: usize,
352	) -> Result<usize> {
353	    let source = shared.source();
354	    let tokens = shared.tokens();
355	    let mut count = 0;
356	    let mut current = target;
357	    loop {
358	        if count == chain.len() {
359	            return Err(limit(vexel_scene::LimitKind::Depth, offset));
360	        }
361	        let token = tokens.get(current.0).ok_or_else(|| invalid(offset))?;
362	        let is_linear = eq(source, token.local_name, b"linearGradient");
363	        let is_radial = eq(source, token.local_name, b"radialGradient");
364	        if (!is_linear && !is_radial) || is_linear != linear || token.prefix.length != 0 {
365	            return Err(unsupported(offset));
366	        }
367	        attributes_supported(source, tokens, current.0, linear, cache, control, offset)?;
368	        chain[count] = current;
369	        count += 1;
370	        let Some(href) = gradient_href(source, tokens, current.0, offset)? else {
371	            return Ok(count);
372	        };
373	        let id = XmlSpan {
374	            offset: href.offset + 1,
375	            length: href.length - 1,
376	        };
377	        let parent = shared
378	            .find_reference(id, control)
379	            .map_err(|error| remap(error, offset))?
380	            .ok_or_else(|| unsupported(offset))?;
381	        if chain[..count].contains(&parent) {
382	            return Err(unsupported(offset));
383	        }
384	        current = parent;
385	    }
386	}
