388	fn attributes_supported(
389	    source: &[u8],
390	    tokens: &[XmlToken],
391	    element: usize,
392	    linear: bool,
393	    cache: &mut vexel_scene::PaintCache,
394	    control: &mut PaintControl<'_>,
395	    offset: usize,
396	) -> Result<()> {
397	    let mut i = element
398	        .checked_add(1)
399	        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
400	    while tokens
401	        .get(i)
402	        .is_some_and(|token| token.kind == TokenKind::Attribute)
403	    {
404	        cache::token_visit(cache, control, offset)?;
405	        let token = &tokens[i];
406	        let name = token.local_name;
407	        let href = eq(source, name, b"href")
408	            && (token.prefix.length == 0
409	                || (eq(source, token.prefix, b"xlink")
410	                    && vexel_svg_reference::xlink_is_bound(source, tokens)));
411	        let common = token.prefix.length == 0
412	            && [
413	                b"id".as_slice(),
414	                b"class",
415	                b"style",
416	                b"gradientUnits",
417	                b"spreadMethod",
418	                b"gradientTransform",
419	            ]
420	            .iter()
421	            .any(|n| eq(source, name, n));
422	        let coordinates: &[&[u8]] = if linear {
423	            &[b"x1", b"y1", b"x2", b"y2"]
424	        } else {
425	            &[b"cx", b"cy", b"r", b"fx", b"fy"]
426	        };
427	        let coordinate =
428	            token.prefix.length == 0 && coordinates.iter().any(|n| eq(source, name, n));
429	        if !href && !common && !coordinate {
430	            return Err(unsupported(offset));
431	        }
432	        i += 1;
433	    }
434	    Ok(())
435	}
