188	fn element_end(
189	    tokens: &[XmlToken],
190	    start: usize,
191	    cache: &mut vexel_scene::PaintCache,
192	    control: &mut PaintControl<'_>,
193	    offset: usize,
194	) -> Result<usize> {
195	    let token = tokens.get(start).ok_or_else(|| invalid(offset))?;
196	    if token.kind == TokenKind::EmptyElement {
197	        return Ok(start);
198	    }
199	    for i in start.saturating_add(1)..tokens.len() {
200	        cache::token_visit(cache, control, offset)?;
201	        if tokens[i].kind == TokenKind::EndElement && tokens[i].depth == token.depth {
202	            return Ok(i);
203	        }
204	    }
205	    Ok(start)
206	}
