208	pub(crate) fn read_definition_attributes(
209	    source: &[u8],
210	    tokens: &[XmlToken],
211	    chain: &[ElementId],
212	    paint: &mut Paint,
213	    offset: usize,
214	) -> Result<()> {
215	    let (mut units, mut spread, mut transform) = (false, false, false);
216	    for element in chain {
217	        if !units {
218	            if let Some(value) = attr(source, tokens, element.0, b"gradientUnits") {
219	                if eq(source, value, b"userSpaceOnUse") {
220	                    paint.object_bounding_box = false;
221	                } else if !eq(source, value, b"objectBoundingBox") {
222	                    return Err(unsupported(offset));
223	                }
224	                units = true;
225	            }
226	        }
227	        if !spread {
228	            if let Some(value) = attr(source, tokens, element.0, b"spreadMethod") {
229	                paint.spread = if eq(source, value, b"reflect") {
230	                    Spread::Reflect
231	                } else if eq(source, value, b"repeat") {
232	                    Spread::Repeat
233	                } else if eq(source, value, b"pad") {
234	                    Spread::Pad
235	                } else {
236	                    return Err(unsupported(offset));
237	                };
238	                spread = true;
239	            }
240	        }
241	        if !transform {
242	            if let Some(value) = attr(source, tokens, element.0, b"gradientTransform") {
243	                let span = Span::from_offset_length(value.offset, value.length)
244	                    .ok_or_else(|| invalid(offset))?;
245	                let (matrix, _) =
246	                    parse_transform(source, span).map_err(|error| unsupported(error.offset))?;
247	                paint.gradient_inverse =
248	                    affine_inverse(matrix).ok_or_else(|| unsupported(offset))?;
249	                transform = true;
250	            }
251	        }
252	    }
253	    Ok(())
254	}
