 62	    /// Explicitly request a separate owned payload. Unlike cached publication,
 63	    /// this copies stops and returns the actual-capacity lease for its lifetime.
 64	    pub fn to_owned(
 65	        &self,
 66	        ledger: &mut ChargeLedger,
 67	        work: &mut dyn WorkControl,
 68	    ) -> Result<OwnedPaint> {
 69	        if !Arc::ptr_eq(self.source, ledger.source_owner()) {
 70	            return Err(invalid(self.offset));
 71	        }
 72	        let mut control = PaintControl::new(ledger, work);
 73	        let result = (|| {
 74	            if self.stops.len() > crate::MAX_GRADIENT_STOPS {
 75	                return Err(limit(LimitKind::PaintStops, self.offset));
 76	            }
 77	            if self.stops.len() < 2
 78	                || self.paint.stops
 79	                    != (vexel_scene::TableRange {
 80	                        first: 0,
 81	                        count: self.stops.len(),
 82	                    })
 83	            {
 84	                return Err(invalid(self.offset));
 85	            }
 86	            let mut previous = 0.0;
 87	            for (index, stop) in self.stops.iter().enumerate() {
 88	                control
 89	                    .charge(WorkKind::PaintVisit, 1)
 90	                    .map_err(|_| limit(LimitKind::Work, self.offset))?;
 91	                if !stop.offset.is_finite()
 92	                    || !(0.0..=1.0).contains(&stop.offset)
 93	                    || (index != 0 && stop.offset < previous)
 94	                {
 95	                    return Err(invalid(self.offset));
 96	                }
 97	                previous = stop.offset;
 98	            }
 99	            control
100	                .checkpoint()
101	                .map_err(|_| limit(LimitKind::Work, self.offset))?;
102	            let requested = self
103	                .stops
104	                .len()
105	                .checked_mul(std::mem::size_of::<PaintStop>())
106	                .ok_or_else(|| limit(LimitKind::Arithmetic, self.offset))?;
107	            if requested > control.ledger.available() {
108	                return Err(limit(LimitKind::ReservedBytes, self.offset));
109	            }
110	            let mut stops = Vec::new();
111	            stops
112	                .try_reserve_exact(self.stops.len())
113	                .map_err(|_| oom(self.offset))?;
114	            let lease = control.ledger.admit_vec(AllocationTag::None, &stops)?;
115	            let copied = (|| {
116	                let mut bytes = requested;
117	                while bytes != 0 {
118	                    let batch = bytes.min(256);
119	                    control
120	                        .charge(WorkKind::SourceRead, batch as u64)
121	                        .map_err(|_| limit(LimitKind::Work, self.offset))?;
122	                    bytes -= batch;
123	                }
124	                control
125	                    .checkpoint()
126	                    .map_err(|_| limit(LimitKind::Work, self.offset))?;
127	                Ok(())
128	            })();
129	            if let Err(error) = copied {
130	                control.ledger.release(lease)?;
131	                return Err(error);
132	            }
133	            stops.extend_from_slice(self.stops);
134	            Ok(OwnedPaint {
135	                resolved: ResolvedPaint {
136	                    paint: self.paint,
137	                    stops,
138	                    template: Some(self.template.clone()),
139	                },
140	                lease,
141	            })
142	        })();
143	        control.result_at(result, self.offset)
144	    }
145	}
