147	/// A deliberately copied compatibility payload plus its releasable job lease.
148	#[must_use = "release the owned capacity lease, transfer both parts, or retain it for the source job"]
149	#[derive(Debug)]
150	pub struct OwnedPaint {
151	    resolved: ResolvedPaint,
152	    lease: AllocationLease,
153	}
154	impl OwnedPaint {
155	    pub fn as_resolved(&self) -> &ResolvedPaint {
156	        &self.resolved
157	    }
158	    /// Consume after publication/use, dropping the allocation and releasing it.
159	    /// A wrong ledger returns the error and owner intact for a correct retry.
160	    pub fn release(
161	        self,
162	        ledger: &mut ChargeLedger,
163	    ) -> std::result::Result<(), (vexel_scene::Diagnostic, Self)> {
164	        match ledger.release(self.lease) {
165	            Ok(()) => Ok(()),
166	            Err(error) => Err((error, self)),
167	        }
168	    }
169	    /// Transfer both payload and lease to a caller that manages its lifetime.
170	    pub fn into_parts(self) -> (ResolvedPaint, AllocationLease) {
171	        (self.resolved, self.lease)
172	    }
173	    /// Compatibility for the frozen DecodeOperations owned return type. Its
174	    /// allocation remains charged for the entire job because that type cannot
175	    /// transport a lease or a cache borrow. Prefer cached graph publication.
176	    pub fn into_job_owned(self) -> ResolvedPaint {
177	        self.resolved
178	    }
179	}
