  4	/// Couples accepted job accounting to caller cancellation/work control.
  5	pub(crate) struct PaintControl<'a> {
  6	    pub(crate) ledger: &'a mut ChargeLedger,
  7	    pub(crate) outer: &'a mut dyn WorkControl,
  8	    failure: Option<Diagnostic>,
  9	}
 10	
 11	impl<'a> PaintControl<'a> {
 12	    pub(crate) fn new(ledger: &'a mut ChargeLedger, outer: &'a mut dyn WorkControl) -> Self {
 13	        Self {
 14	            ledger,
 15	            outer,
 16	            failure: None,
 17	        }
 18	    }
 19	    pub(crate) fn result_at<T>(&mut self, result: Result<T>, offset: usize) -> Result<T> {
 20	        match result {
 21	            Ok(value) => Ok(value),
 22	            Err(error) => {
 23	                let mut diagnostic = self.failure.take().unwrap_or(error);
 24	                diagnostic.offset = offset;
 25	                Err(diagnostic)
 26	            }
 27	        }
 28	    }
 29	}
