 31	impl WorkControl for PaintControl<'_> {
 32	    fn charge(&mut self, kind: WorkKind, units: u64) -> std::result::Result<(), Stop> {
 33	        if let Err(error) = self.ledger.work.charge(kind, units) {
 34	            let stop = stop_for(&error);
 35	            self.failure = Some(error);
 36	            return Err(stop);
 37	        }
 38	        if let Err(stop) = self.outer.charge(kind, units) {
 39	            self.failure = Some(from_stop(stop, 0));
 40	            return Err(stop);
 41	        }
 42	        Ok(())
 43	    }
 44	    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
 45	        if let Err(stop) = self.outer.checkpoint() {
 46	            self.failure = Some(from_stop(stop, 0));
 47	            return Err(stop);
 48	        }
 49	        Ok(())
 50	    }
 51	}
 52	
 53	fn from_stop(stop: Stop, offset: usize) -> Diagnostic {
 54	    let kind = match stop {
 55	        Stop::Canceled => ErrorKind::Canceled,
 56	        Stop::Overflow => ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic),
 57	        Stop::Limit => ErrorKind::Limit(vexel_scene::LimitKind::Work),
 58	    };
 59	    Diagnostic { kind, offset }
 60	}
 61	
 62	fn stop_for(error: &Diagnostic) -> Stop {
 63	    match error.kind {
 64	        ErrorKind::OutOfMemory => Stop::Limit,
 65	        ErrorKind::Canceled => Stop::Canceled,
 66	        ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic) => Stop::Overflow,
 67	        ErrorKind::Limit(_) => Stop::Limit,
 68	        _ => Stop::Limit,
 69	    }
 70	}

