 53	static size_t cache_hash(uint32_t token_index, double viewport_width,
 54	                        double viewport_height)
 55	{
 56	    uint64_t width_bits = 0U, height_bits = 0U;
 57	    memcpy(&width_bits, &viewport_width, sizeof(width_bits));
 58	    memcpy(&height_bits, &viewport_height, sizeof(height_bits));
 59	    uint64_t value = (uint64_t)token_index ^ width_bits ^
 60	                     (height_bits + UINT64_C(0x9e3779b97f4a7c15));
 61	    value ^= value >> 30U;
 62	    value *= UINT64_C(0xbf58476d1ce4e5b9);
 63	    value ^= value >> 27U;
 64	    value *= UINT64_C(0x94d049bb133111eb);
 65	    value ^= value >> 31U;
 66	    return (size_t)value & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
 67	}
 68	
 69	static svg_shape_error cache_create(svg_paint_cache **out)
 70	{
 71	    if (out == NULL) return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
 72	    if (*out != NULL) return SVG_SHAPE_ERROR_NONE;
 73	    if (SVG_PAINT_CACHE_SLOT_COUNT > SIZE_MAX / sizeof(uint32_t))
 74	        return SVG_SHAPE_ERROR_LIMIT;
 75	    svg_paint_cache *cache = svg_shape_calloc(1U, sizeof(*cache));
 76	    if (cache == NULL) return SVG_SHAPE_ERROR_OOM;
 77	    cache->slots = svg_shape_calloc(SVG_PAINT_CACHE_SLOT_COUNT,
 78	                                    sizeof(*cache->slots));
 79	    if (cache->slots == NULL) {
 80	        svg_shape_free(cache);
 81	        return SVG_SHAPE_ERROR_OOM;
 82	    }
 83	    *out = cache;
 84	    return SVG_SHAPE_ERROR_NONE;
 85	}
