 87	static svg_cached_gradient *cache_find(svg_paint_cache *cache,
 88	                                       uint32_t token_index,
 89	                                       double viewport_width,
 90	                                       double viewport_height)
 91	{
 92	    if (cache == NULL || cache->slots == NULL) return NULL;
 93	    size_t slot = cache_hash(token_index, viewport_width, viewport_height);
 94	    for (size_t probes = 0U; probes < SVG_PAINT_CACHE_SLOT_COUNT; ++probes) {
 95	        uint32_t stored = cache->slots[slot];
 96	        if (stored == 0U) return NULL;
 97	        size_t entry = (size_t)(stored - 1U);
 98	        if (entry < cache->entry_count &&
 99	            cache->entries[entry].token_index == token_index &&
100	            cache->entries[entry].viewport_width == viewport_width &&
101	            cache->entries[entry].viewport_height == viewport_height)
102	            return &cache->entries[entry];
103	        slot = (slot + 1U) & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
104	    }
105	    return NULL;
106	}
