108	static svg_shape_error cache_reserve_entry(svg_paint_cache *cache)
109	{
110	    if (cache->entry_count >= SVG_PAINT_CACHE_MAX_GRADIENTS ||
111	        cache->entry_count >= UINT32_MAX) return SVG_SHAPE_ERROR_LIMIT;
112	    if (cache->entry_count == cache->entry_capacity) {
113	        size_t capacity = cache->entry_capacity == 0U ? 16U :
114	                          cache->entry_capacity * 2U;
115	        if (capacity < cache->entry_capacity) return SVG_SHAPE_ERROR_LIMIT;
116	        if (capacity > SVG_PAINT_CACHE_MAX_GRADIENTS)
117	            capacity = SVG_PAINT_CACHE_MAX_GRADIENTS;
118	        if (capacity > SIZE_MAX / sizeof(*cache->entries))
119	            return SVG_SHAPE_ERROR_LIMIT;
120	        svg_cached_gradient *grown = svg_shape_realloc(
121	            cache->entries, capacity * sizeof(*cache->entries));
122	        if (grown == NULL) return SVG_SHAPE_ERROR_OOM;
123	        cache->entries = grown;
124	        cache->entry_capacity = capacity;
125	    }
126	    return SVG_SHAPE_ERROR_NONE;
127	}
