129	static svg_shape_error cache_insert(svg_paint_cache *cache,
130	                                    const svg_cached_gradient *gradient,
131	                                    svg_cached_gradient **out)
132	{
133	    if (cache->entry_count >= cache->entry_capacity ||
134	        cache->entry_count >= SVG_PAINT_CACHE_MAX_GRADIENTS ||
135	        cache->entry_count >= UINT32_MAX) return SVG_SHAPE_ERROR_LIMIT;
136	    size_t entry = cache->entry_count;
137	    cache->entries[entry] = *gradient;
138	    size_t slot = cache_hash(gradient->token_index,
139	                             gradient->viewport_width,
140	                             gradient->viewport_height);
141	    for (size_t probes = 0U; probes < SVG_PAINT_CACHE_SLOT_COUNT; ++probes) {
142	        if (cache->slots[slot] == 0U) {
143	            cache->slots[slot] = (uint32_t)(entry + 1U);
144	            cache->entry_count++;
145	            *out = &cache->entries[entry];
146	            return SVG_SHAPE_ERROR_NONE;
147	        }
148	        slot = (slot + 1U) & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
149	    }
150	    return SVG_SHAPE_ERROR_LIMIT;
151	}
