181	static bool gradient_attributes_supported(base_bytes source,
182	                                          const svg_xml_token *tokens,
183	                                          size_t count, size_t gradient,
184	                                          bool linear,
185	                                          size_t *token_visits,
186	                                          bool *hit_limit)
187	{
188	    *hit_limit = false;
189	    for (size_t i = gradient + 1U;
190	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
191	        if (!count_token_visit(token_visits)) {
192	            *hit_limit = true;
193	            return false;
194	        }
195	        svg_xml_span name = tokens[i].local_name;
196	        bool href = eq(source, name, "href") &&
197	            (tokens[i].prefix.length == 0U ||
198	             (eq(source, tokens[i].prefix, "xlink") &&
199	              svg_reference_xlink_is_bound(source, tokens, count)));
200	        bool common = tokens[i].prefix.length == 0U &&
201	            (eq(source, name, "id") || eq(source, name, "class") ||
202	             eq(source, name, "style") || eq(source, name, "gradientUnits") ||
203	             eq(source, name, "spreadMethod") ||
204	             eq(source, name, "gradientTransform"));
205	        bool coordinate = tokens[i].prefix.length == 0U &&
206	            (linear ? (eq(source, name, "x1") || eq(source, name, "y1") ||
207	                       eq(source, name, "x2") || eq(source, name, "y2")) :
208	                      (eq(source, name, "cx") || eq(source, name, "cy") ||
209	                       eq(source, name, "r") || eq(source, name, "fx") ||
210	                       eq(source, name, "fy")));
211	        if (!href && !common && !coordinate) return false;
212	    }
213	    return true;
214	}
