222	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
223	        if (!eq(source, tokens[i].local_name, "href")) continue;
224	        if (*present ||
225	            (tokens[i].prefix.length != 0U &&
226	             (!eq(source, tokens[i].prefix, "xlink") ||
227	              !svg_reference_xlink_is_bound(source, tokens, count))) ||
228	            tokens[i].value.offset > source.len ||
229	            tokens[i].value.length < 2U ||
230	            tokens[i].value.length > source.len - tokens[i].value.offset ||
231	            source.ptr[tokens[i].value.offset] != '#') return false;
232	        *present = true;
233	        *value = tokens[i].value;
234	    }
235	    return true;
