238	static svg_css_error gradient_inherited_color(
239	    svg_css_sheet *css, base_bytes source, const svg_xml_token *tokens,
240	    size_t count, size_t gradient, size_t *token_visits,
241	    svg_css_paint *color_style)
242	{
243	    size_t ancestors[64];
244	    size_t ancestor_count = 0U;
245	    for (size_t i = 0U; i <= gradient; ++i) {
246	        if (!count_token_visit(token_visits)) return SVG_CSS_LIMIT;
247	        if (tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
248	            tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) continue;
249	        while (ancestor_count != 0U &&
250	               tokens[ancestors[ancestor_count - 1U]].depth >= tokens[i].depth)
251	            ancestor_count--;
252	        if (ancestor_count == sizeof(ancestors) / sizeof(ancestors[0]))
253	            return SVG_CSS_LIMIT;
254	        ancestors[ancestor_count++] = i;
255	    }
256	    svg_css_paint inherited = svg_css_initial_paint();
257	    for (size_t i = 0U; i < ancestor_count; ++i) {
258	        svg_css_paint computed;
259	        svg_css_error error = svg_css_compute(css, source, tokens, count,
260	            ancestors[i], i == 0U ? NULL : &inherited, &computed);
261	        if (error != SVG_CSS_OK) return error;
262	        inherited = computed;
263	    }
264	    *color_style = (svg_css_paint){0};
265	    if (inherited.values[SVG_CSS_COLOR].present)
266	        color_style->values[SVG_CSS_COLOR] = inherited.values[SVG_CSS_COLOR];
267	    return SVG_CSS_OK;
268	}
