274	        *end = start;
275	        return true;
276	    }
277	    for (size_t i = start + 1U; i < count; ++i) {
278	        if (!count_token_visit(token_visits)) return false;
279	        if (tokens[i].kind == SVG_XML_TOKEN_END_ELEMENT &&
280	            tokens[i].depth == tokens[start].depth) {
281	            *end = i;
282	            return true;
283	        }
284	    }
285	    *end = start;
286	    return true;
287	}
