289	static bool number(base_bytes source, svg_xml_span span, double *out)
290	{
291	    if (span.offset > source.len || span.length == 0U ||
292	        span.length >= 96U || span.length > source.len - span.offset) return false;
293	    char text[96];
294	    memcpy(text, source.ptr + span.offset, span.length);
295	    text[span.length] = '\0';
296	    char *end = NULL;
297	    *out = strtod(text, &end);
298	    if (end == text || !isfinite(*out) || fabs(*out) > 1000000.0) return false;
299	    bool percent = *end == '%';
300	    if (percent) ++end;
301	    if (*end != '\0') return false;
302	    if (percent) *out /= 100.0;
303	    return true;
304	}
