311	static bool resolve_stop_color(base_bytes source, svg_xml_span span,
312	                               const svg_css_paint *style,
313	                               uint8_t rgba[4])
314	{
315	    if (!svg_css_keyword_equals(source, span, "currentColor"))
316	        return color(source, span, rgba);
317	    svg_xml_span color_value;
318	    if (!svg_css_paint_value(style, SVG_CSS_COLOR, &color_value) ||
319	        svg_css_keyword_equals(source, color_value, "currentColor")) {
320	        rgba[0] = rgba[1] = rgba[2] = 0U;
321	        rgba[3] = 255U;
322	        return true;
323	    }
324	    return color(source, color_value, rgba);
325	}
326	
327	static bool supported_stop_inline_style(base_bytes source, svg_xml_span style)
328	{
329	    size_t i = style.offset, end = style.offset + style.length;
330	    while (i < end) {
331	        while (i < end && (source.ptr[i] == ' ' || source.ptr[i] == '\t' ||
332	                           source.ptr[i] == '\r' || source.ptr[i] == '\n' ||
333	                           source.ptr[i] == ';')) i++;
334	        if (i == end) break;
335	        size_t name = i;
336	        while (i < end && source.ptr[i] != ':' && source.ptr[i] != ';') i++;
337	        if (i == end || source.ptr[i] != ':') return false;
338	        size_t name_end = i;
339	        while (name_end > name && (source.ptr[name_end - 1U] == ' ' ||
340	                                   source.ptr[name_end - 1U] == '\t')) name_end--;
341	        svg_xml_span property = {name, name_end - name};
342	        if (!eq(source, property, "stop-color") &&
343	            !eq(source, property, "stop-opacity") &&
344	            !eq(source, property, "color")) return false;
345	        i++;
346	        while (i < end && source.ptr[i] != ';') i++;
347	        if (i < end) i++;
348	    }
349	    return true;
350	}
351	
352	static bool parse_stops(svg_css_sheet *css, base_bytes source,
353	                        const svg_xml_token *tokens, size_t count,
354	                        size_t gradient, const svg_css_paint *gradient_style,
355	                        size_t *token_visits,
356	                        svg_paint_stop stops[SVG_PAINT_MAX_GRADIENT_STOPS],
357	                        size_t *stop_count, bool *has_stop_elements,
358	                        bool *hit_limit, bool *hit_oom)
359	{
360	    *has_stop_elements = false;
361	    *hit_limit = false;
362	    *hit_oom = false;
363	    size_t end = gradient;
364	    if (!element_end(tokens, count, gradient, token_visits, &end)) {
365	        *hit_limit = true;
366	        return false;
367	    }
368	    size_t n = 0U;
369	    for (size_t i = gradient + 1U; i < end; ++i) {
370	        if (!count_token_visit(token_visits)) {
371	            *hit_limit = true;
372	            return false;
373	        }
374	        if ((tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
375	             tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) ||
376	            tokens[i].depth != tokens[gradient].depth + 1U) continue;
377	        *has_stop_elements = true;
378	        if (!eq(source, tokens[i].local_name, "stop") ||
379	            tokens[i].prefix.length != 0U) return false;
380	        if (n == SVG_PAINT_MAX_GRADIENT_STOPS) { *hit_limit = true; return false; }
381	        svg_xml_span offset = {0}, stop_color = {0}, opacity = {0}, style = {0};
382	        (void)attr(source, tokens, count, i, "offset", &offset);
383	        if (attr(source, tokens, count, i, "style", &style) &&
384	            !supported_stop_inline_style(source, style)) return false;
385	        svg_css_paint computed;
386	        svg_css_error css_error = svg_css_compute(css, source, tokens, count, i,
387	                                                 gradient_style, &computed);
388	        if (css_error != SVG_CSS_OK) {
389	            *hit_limit = css_error == SVG_CSS_LIMIT;
390	            *hit_oom = css_error == SVG_CSS_OOM;
391	            return false;
392	        }
393	        for (size_t property = 0U; property < SVG_CSS_PROPERTY_COUNT; ++property) {
394	            if (property != SVG_CSS_STOP_COLOR &&
395	                property != SVG_CSS_STOP_OPACITY && property != SVG_CSS_COLOR &&
396	                computed.values[property].present) return false;
397	        }
398	        bool has_stop_color = svg_css_paint_value(
399	            &computed, SVG_CSS_STOP_COLOR, &stop_color);
400	        bool has_opacity = svg_css_paint_value(
401	            &computed, SVG_CSS_STOP_OPACITY, &opacity);
402	        double position = 0.0, alpha = 1.0;
403	        if (offset.length != 0U && !number(source, offset, &position)) return false;
404	        if (has_opacity && !number(source, opacity, &alpha)) return false;
405	        if (position < 0.0 || position > 1.0 || alpha < 0.0 || alpha > 1.0 ||
406	            (n != 0U && position < stops[n - 1U].offset)) return false;
407	        if (!has_stop_color) {
408	            stops[n].rgba[0] = stops[n].rgba[1] = stops[n].rgba[2] = 0U;
409	            stops[n].rgba[3] = 255U;
410	        } else if (stop_color.length == 0U ||
411	                   !resolve_stop_color(source, stop_color, &computed,
412	                                       stops[n].rgba))
413	            return false;
414	        stops[n].offset = position;
415	        stops[n].rgba[3] = (uint8_t)lround((double)stops[n].rgba[3] * alpha);
416	        ++n;
417	        if (tokens[i].kind == SVG_XML_TOKEN_START_ELEMENT) {
418	            size_t stop_end = i;
419	            if (!element_end(tokens, count, i, token_visits, &stop_end)) {
420	                *hit_limit = true;
421	                return false;
422	            }
423	            i = stop_end;
424	        }
425	    }
426	    if (n < 2U) return false;
427	    *stop_count = n;
428	    return true;
429	}
430	
431	static bool gradient_coordinates(base_bytes source, const svg_xml_token *tokens,
432	                                 size_t count, const size_t *chain,
433	                                 size_t chain_count, bool object_box,
434	                                 double viewport_width, double viewport_height,
435	                                 svg_shape_paint *paint)
436	{
437	    static const char *const linear_names[4] = {"x1", "y1", "x2", "y2"};
438	    static const char *const radial_names[5] = {"cx", "cy", "r", "fx", "fy"};
439	    const char *const *names = paint->kind == SVG_SHAPE_PAINT_LINEAR ?
440	        linear_names : radial_names;
441	    double diagonal = hypot(viewport_width, viewport_height) / sqrt(2.0);
442	    double defaults[5] = {0.0};
443	    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
444	        defaults[2] = object_box ? 1.0 : viewport_width;
445	    } else {
446	        defaults[0] = object_box ? 0.5 : viewport_width * 0.5;
447	        defaults[1] = object_box ? 0.5 : viewport_height * 0.5;
448	        defaults[2] = object_box ? 0.5 : diagonal * 0.5;
449	        defaults[3] = defaults[0];
450	        defaults[4] = defaults[1];
451	    }
452	    size_t coordinate_count = paint->kind == SVG_SHAPE_PAINT_LINEAR ? 4U : 5U;
453	    bool coordinate_found[5] = {false, false, false, false, false};
454	    for (size_t coordinate = 0U; coordinate < coordinate_count; ++coordinate) {
455	        paint->coordinates[coordinate] = defaults[coordinate];
456	        for (size_t definition = 0U; definition < chain_count; ++definition) {
457	            svg_xml_span value;
458	            if (!attr(source, tokens, count, chain[definition],
459	                      names[coordinate], &value)) continue;
460	            coordinate_found[coordinate] = true;
461	            double reference = object_box ? 1.0 :
462	                (paint->kind == SVG_SHAPE_PAINT_LINEAR ?
463	                    ((coordinate & 1U) == 0U ? viewport_width : viewport_height) :
464	                    coordinate == 2U ? diagonal :
465	                    (coordinate == 0U || coordinate == 3U ?
466	                        viewport_width : viewport_height));
467	            if (object_box) {
468	                size_t end = value.offset + value.length;
469	                for (size_t at = value.offset; at < end; ++at) {
470	                    uint8_t byte = source.ptr[at];
471	                    if ((byte >= 'a' && byte <= 'z') ||
472	                        (byte >= 'A' && byte <= 'Z')) return false;
473	                }
474	            }
475	            if (!svg_shape_read_length(source, value, reference,
476	                                       &paint->coordinates[coordinate]))
477	                return false;
478	            break;
479	        }
480	    }
481	    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[3]) paint->coordinates[3] = paint->coordinates[0];
482	    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[4]) paint->coordinates[4] = paint->coordinates[1];
483	    return paint->kind != SVG_SHAPE_PAINT_RADIAL ||
484	           (paint->coordinates[2] > 0.0 && isfinite(paint->coordinates[2]));
485	}
486	
487	static bool collect_gradient_chain(base_bytes source,
488	                                   const svg_xml_token *tokens,
489	                                   size_t token_count,
490	                                   svg_reference_index *references,
491	                                   size_t target, bool linear,
492	                                   size_t *token_visits, size_t chain[16],
493	                                   size_t *chain_count, bool *hit_limit)
494	{
495	    *chain_count = 0U;
496	    *hit_limit = false;
497	    size_t current = target;
498	    while (true) {
499	        if (*chain_count == 16U) {
500	            *hit_limit = true;
501	            return false;
502	        }
503	        bool current_linear = eq(source, tokens[current].local_name,
504	                                 "linearGradient");
505	        bool current_radial = eq(source, tokens[current].local_name,
506	                                 "radialGradient");
507	        if ((!current_linear && !current_radial) || current_linear != linear ||
508	            tokens[current].prefix.length != 0U) return false;
509	        bool attr_limit = false;
510	        if (!gradient_attributes_supported(source, tokens, token_count,
511	                current, linear, token_visits, &attr_limit)) {
512	            *hit_limit = attr_limit;
513	            return false;
514	        }
515	        chain[(*chain_count)++] = current;
516	        bool has_href = false;
517	        svg_xml_span href = {0};
518	        if (!gradient_href(source, tokens, token_count, current,
519	                           &has_href, &href)) return false;
520	        if (!has_href) return true;
521	        svg_xml_span id = {href.offset + 1U, href.length - 1U};
522	        size_t parent;
523	        if (!svg_reference_index_find(source, tokens, token_count,
524	                                      references, id, &parent)) return false;
525	        for (size_t i = 0U; i < *chain_count; ++i)
526	            if (chain[i] == parent) return false;
527	        current = parent;
528	    }
529	}
530	
531	svg_shape_error svg_paint_resolve_fill(base_bytes source,
532	                                       const svg_xml_token *tokens,
533	                                       size_t token_count,
534	                                       svg_reference_index *references,
535	                                       svg_css_sheet *css,
536	                                       svg_paint_cache **cache,
537	                                       size_t *token_visits,
538	                                       svg_xml_span fill,
539	                                       const geom_edge *edges, size_t edge_count,
540	                                       geom_affine user_inverse,
541	                                       double viewport_width, double viewport_height,
542	                                       svg_shape_paint *paint,
543	                                       svg_paint_stop **stops,
544	                                       size_t *stop_count,
545	                                       svg_shape_diagnostic *diagnostic)
546	{
547	    if (cache == NULL || stops == NULL || stop_count == NULL || paint == NULL) {
548	        if (diagnostic != NULL)
549	            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_INVALID_ARGUMENT,
550	                                                 fill.offset};
551	        return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
552	    }
553	    if (fill.length < 7U || fill.offset > source.len ||
554	        fill.length > source.len - fill.offset ||
555	        memcmp(source.ptr + fill.offset, "url(#", 5U) != 0 ||
556	        source.ptr[fill.offset + fill.length - 1U] != ')') return SVG_SHAPE_ERROR_UNSUPPORTED;
557	    svg_xml_span target_id = {fill.offset + 5U, fill.length - 6U};
558	    size_t target;
559	    if (!svg_reference_index_find(source, tokens, token_count, references,
560	                                  target_id, &target)) goto unsupported;
561	    if (target > UINT32_MAX) goto limit;
562	    bool linear = eq(source, tokens[target].local_name, "linearGradient");
563	    bool radial = eq(source, tokens[target].local_name, "radialGradient");
564	    if ((!linear && !radial) || tokens[target].prefix.length != 0U)
565	        goto unsupported;
566	
567	    svg_cached_gradient *cached = cache_find(*cache, (uint32_t)target,
568	                                             viewport_width,
569	                                             viewport_height);
570	    if (cached == NULL) {
571	        svg_shape_error cache_error = cache_create(cache);
572	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
573	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
574	
575	        size_t chain[16], chain_count = 0U;
576	        bool chain_limit = false;
577	        if (!collect_gradient_chain(source, tokens, token_count, references,
578	                target, linear, token_visits, chain, &chain_count,
579	                &chain_limit)) {
580	            if (chain_limit) goto limit;
581	            goto unsupported;
582	        }
583	        svg_shape_paint definition = {0};
584	        definition.kind = linear ? SVG_SHAPE_PAINT_LINEAR :
585	                                   SVG_SHAPE_PAINT_RADIAL;
586	        definition.object_bounding_box = true;
587	        definition.spread_method = SVG_SHAPE_SPREAD_PAD;
588	        definition.gradient_inverse = geom_affine_identity();
589	        bool found_units = false, found_spread = false, found_transform = false;
590	        for (size_t i = 0U; i < chain_count; ++i) {
591	            svg_xml_span value;
592	            if (!found_units && attr(source, tokens, token_count, chain[i],
593	                                     "gradientUnits", &value)) {
594	                if (eq(source, value, "userSpaceOnUse"))
595	                    definition.object_bounding_box = false;
596	                else if (!eq(source, value, "objectBoundingBox"))
597	                    goto unsupported;
598	                found_units = true;
599	            }
600	            if (!found_spread && attr(source, tokens, token_count, chain[i],
601	                                      "spreadMethod", &value)) {
602	                if (eq(source, value, "reflect"))
603	                    definition.spread_method = SVG_SHAPE_SPREAD_REFLECT;
604	                else if (eq(source, value, "repeat"))
605	                    definition.spread_method = SVG_SHAPE_SPREAD_REPEAT;
606	                else if (!eq(source, value, "pad"))
607	                    goto unsupported;
608	                found_spread = true;
609	            }
610	            if (!found_transform && attr(source, tokens, token_count, chain[i],
611	                                         "gradientTransform", &value)) {
612	                geom_affine transform;
613	                size_t operations = 0U;
614	                if (!svg_shape_transform_parse(source, value, &transform,
615	                                               &operations) ||
616	                    !svg_shape_affine_inverse(transform,
617	                                              &definition.gradient_inverse))
618	                    goto unsupported;
619	                (void)operations;
620	                found_transform = true;
621	            }
622	        }
623	        if (!gradient_coordinates(source, tokens, token_count, chain,
624	                chain_count, definition.object_bounding_box, viewport_width,
625	                viewport_height, &definition)) goto unsupported;
626	
627	        svg_paint_stop local[SVG_PAINT_MAX_GRADIENT_STOPS];
628	        size_t local_count = 0U;
629	        bool inherited_stops = false;
630	        for (size_t i = 0U; i < chain_count; ++i) {
631	            svg_css_paint parent_color = {0};
632	            svg_css_error css_error = gradient_inherited_color(
633	                css, source, tokens, token_count, chain[i], token_visits,
634	                &parent_color);
635	            if (css_error == SVG_CSS_LIMIT) goto limit;
636	            if (css_error == SVG_CSS_OOM) goto oom;
637	            if (css_error != SVG_CSS_OK) goto unsupported;
638	            bool has_stop_elements = false, stop_limit = false, stop_oom = false;
639	            if (parse_stops(css, source, tokens, token_count, chain[i],
640	                    &parent_color, token_visits, local, &local_count,
641	                    &has_stop_elements, &stop_limit, &stop_oom)) {
642	                inherited_stops = true;
643	                break;
644	            }
645	            if (stop_limit) goto limit;
646	            if (stop_oom) goto oom;
647	            if (has_stop_elements) goto unsupported;
648	        }
649	        if (!inherited_stops) goto unsupported;
650	        if (*stop_count > SVG_PAINT_MAX_STOPS ||
651	            local_count > SVG_PAINT_MAX_STOPS - *stop_count) goto limit;
652	        cache_error = cache_reserve_entry(*cache);
653	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
654	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
655	        size_t new_stop_count = *stop_count + local_count;
656	        if (new_stop_count > SIZE_MAX / sizeof(**stops)) goto limit;
657	        svg_paint_stop *grown = svg_shape_realloc(
658	            *stops, new_stop_count * sizeof(**stops));
659	        if (grown == NULL) goto oom;
660	        size_t first_stop = *stop_count;
661	        memcpy(grown + first_stop, local, local_count * sizeof(*local));
662	        *stops = grown;
663	        *stop_count = new_stop_count;
664	
665	        svg_cached_gradient pending = {0};
666	        pending.token_index = (uint32_t)target;
667	        pending.viewport_width = viewport_width;
668	        pending.viewport_height = viewport_height;
669	        pending.kind = definition.kind;
670	        pending.spread_method = definition.spread_method;
671	        pending.object_bounding_box = definition.object_bounding_box;
672	        memcpy(pending.coordinates, definition.coordinates,
673	               sizeof(pending.coordinates));
674	        pending.gradient_inverse = definition.gradient_inverse;
675	        pending.first_stop = first_stop;
676	        pending.stop_count = local_count;
677	        cache_error = cache_insert(*cache, &pending, &cached);
678	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
679	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
680	    }
681	
682	    svg_shape_paint result = {0};
683	    result.kind = cached->kind;
684	    result.spread_method = cached->spread_method;
685	    result.object_bounding_box = cached->object_bounding_box;
686	    memcpy(result.coordinates, cached->coordinates, sizeof(result.coordinates));
687	    result.first_stop = cached->first_stop;
688	    result.stop_count = cached->stop_count;
689	    result.user_inverse = user_inverse;
690	    result.gradient_inverse = cached->gradient_inverse;
691	    if (edge_count == 0U) goto unsupported;
692	    geom_point first_local;
693	    if (!geom_affine_map_point(user_inverse, edges[0].a, &first_local))
694	        goto unsupported;
695	    double min_x = first_local.x, min_y = first_local.y;
696	    double max_x = min_x, max_y = min_y;
697	    for (size_t i = 0U; i < edge_count; ++i) {
698	        const geom_point source_points[2] = {edges[i].a, edges[i].b};
699	        for (size_t j = 0U; j < 2U; ++j) {
700	            geom_point point;
701	            if (!geom_affine_map_point(user_inverse, source_points[j], &point))
702	                goto unsupported;
703	            if (point.x < min_x) min_x = point.x;
704	            if (point.x > max_x) max_x = point.x;
705	            if (point.y < min_y) min_y = point.y;
706	            if (point.y > max_y) max_y = point.y;
707	        }
708	    }
709	    result.bounds[0] = min_x; result.bounds[1] = min_y;
710	    result.bounds[2] = max_x; result.bounds[3] = max_y;
711	    if (result.object_bounding_box && (max_x <= min_x || max_y <= min_y)) goto unsupported;
712	    *paint = result;
713	    return SVG_SHAPE_ERROR_NONE;
714	limit:
715	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, fill.offset};
716	    return SVG_SHAPE_ERROR_LIMIT;
717	oom:
718	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, fill.offset};
719	    return SVG_SHAPE_ERROR_OOM;
720	unsupported:
721	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_UNSUPPORTED, fill.offset};
722	    return SVG_SHAPE_ERROR_UNSUPPORTED;
723	}
724	
725	void svg_paint_sample(const svg_shape_paint *paint, const svg_paint_stop *stops,
726	                      double x, double y, uint8_t rgba[4])
727	{
728	    if (paint == NULL || stops == NULL || paint->stop_count < 2U) return;
729	    geom_point local;
730	    if (!geom_affine_map_point(paint->user_inverse, (geom_point){x, y}, &local))
731	        return;
732	    double gx = local.x, gy = local.y, t;
733	    if (paint->object_bounding_box) {
734	        gx = (local.x - paint->bounds[0]) /
735	             (paint->bounds[2] - paint->bounds[0]);
736	        gy = (local.y - paint->bounds[1]) /
737	             (paint->bounds[3] - paint->bounds[1]);
738	    }
739	    geom_point transformed;
740	    if (!geom_affine_map_point(paint->gradient_inverse,
741	                               (geom_point){gx, gy}, &transformed)) return;
742	    gx = transformed.x;
743	    gy = transformed.y;
744	    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
745	        double dx = paint->coordinates[2] - paint->coordinates[0];
746	        double dy = paint->coordinates[3] - paint->coordinates[1];
747	        double length = dx * dx + dy * dy;
748	        t = length == 0.0 ? 1.0 : ((gx - paint->coordinates[0]) * dx +
749	                                   (gy - paint->coordinates[1]) * dy) / length;
750	    } else {
751	        double focal_x = paint->coordinates[3];
752	        double focal_y = paint->coordinates[4];
753	        double center_dx = paint->coordinates[0] - focal_x;
754	        double center_dy = paint->coordinates[1] - focal_y;
755	        double point_dx = gx - focal_x;
756	        double point_dy = gy - focal_y;
757	        double radius = paint->coordinates[2];
758	        double a = center_dx * center_dx + center_dy * center_dy -
759	                   radius * radius;
760	        double b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
761	        double c = point_dx * point_dx + point_dy * point_dy;
762	        if (fabs(a) <= 1e-15) {
763	            if (fabs(b) <= 1e-15) return;
764	            t = -c / b;
765	        } else {
766	            double discriminant = b * b - 4.0 * a * c;
767	            if (discriminant < 0.0 || !isfinite(discriminant)) return;
768	            double root = sqrt(discriminant);
769	            double t0 = (-b - root) / (2.0 * a);
770	            double t1 = (-b + root) / (2.0 * a);
771	            t = fmax(t0, t1);
772	            if (t < 0.0) t = fmin(t0, t1);
773	        }
774	    }
775	    if (!isfinite(t)) return;
776	    if (paint->spread_method == SVG_SHAPE_SPREAD_REPEAT) {
777	        t -= floor(t);
778	    } else if (paint->spread_method == SVG_SHAPE_SPREAD_REFLECT) {
779	        t = fmod(t, 2.0);
780	        if (t < 0.0) t += 2.0;
781	        if (t > 1.0) t = 2.0 - t;
782	    }
783	    if (t <= stops[paint->first_stop].offset) {
784	        memcpy(rgba, stops[paint->first_stop].rgba, 4U);
785	        return;
786	    }
787	    size_t last = paint->first_stop + paint->stop_count - 1U;
788	    if (t >= stops[last].offset) {
789	        memcpy(rgba, stops[last].rgba, 4U);
790	        return;
791	    }
792	    size_t right = paint->first_stop + 1U;
793	    while (right <= last && t > stops[right].offset) ++right;
794	    size_t left = right - 1U;
795	    double range = stops[right].offset - stops[left].offset;
796	    double amount = range <= 0.0 ? 1.0 : (t - stops[left].offset) / range;
797	    for (size_t c = 0U; c < 4U; ++c)
798	        rgba[c] = (uint8_t)lround((1.0 - amount) * stops[left].rgba[c] + amount * stops[right].rgba[c]);
799	}
