  8	/// Checked equivalent of the legacy pointer span helper. `formed` is true
  9	/// only when a nonempty in-range slice was formed.
 10	pub fn edge_span<'a>(
 11	    edges: &'a [Edge],
 12	    first: usize,
 13	    count: usize,
 14	    formed: &mut bool,
 15	) -> Option<&'a [Edge]> {
 16	    *formed = false;
 17	    if count == 0 {
 18	        return None;
 19	    }
 20	    let end = first.checked_add(count)?;
 21	    let result = edges.get(first..end)?;
 22	    *formed = true;
 23	    Some(result)
 24	}
