 26	/// Validates a stop span before sampling. Invalid untrusted paint data or a
 27	/// nonfinite intermediate leaves `rgba` unchanged, matching the C no-write
 28	/// fallbacks without allowing an out-of-range access.
 29	pub fn sample(paint: &Paint, stops: &[PaintStop], x: f64, y: f64, rgba: &mut [u8; 4]) {
 30	    let Some(end) = paint.stops.first.checked_add(paint.stops.count) else {
 31	        return;
 32	    };
 33	    if paint.stops.count < 2 || paint.stops.count > MAX_GRADIENT_STOPS || end > stops.len() {
 34	        return;
 35	    }
 36	    let section = &stops[paint.stops.first..end];
 37	    if !valid_stops(section) {
 38	        return;
 39	    }
 40	    let Some(local) = affine_map_point(paint.user_inverse, Point { x, y }) else {
 41	        return;
 42	    };
 43	    let (mut gx, mut gy) = (local.x, local.y);
 44	    if paint.object_bounding_box {
 45	        let (w, h) = (
 46	            paint.bounds[2] - paint.bounds[0],
 47	            paint.bounds[3] - paint.bounds[1],
 48	        );
 49	        if !w.is_finite() || !h.is_finite() || w <= 0.0 || h <= 0.0 {
 50	            return;
 51	        }
 52	        gx = (local.x - paint.bounds[0]) / w;
 53	        gy = (local.y - paint.bounds[1]) / h;
 54	    }
 55	    let Some(point) = affine_map_point(paint.gradient_inverse, Point { x: gx, y: gy }) else {
 56	        return;
 57	    };
 58	    gx = point.x;
 59	    gy = point.y;
 60	    let t = match paint.kind {
 61	        PaintKind::Linear => {
 62	            let dx = paint.coordinates[2] - paint.coordinates[0];
 63	            let dy = paint.coordinates[3] - paint.coordinates[1];
 64	            let length = dx * dx + dy * dy;
 65	            if length == 0.0 {
 66	                1.0
 67	            } else {
 68	                ((gx - paint.coordinates[0]) * dx + (gy - paint.coordinates[1]) * dy) / length
 69	            }
 70	        }
 71	        PaintKind::Radial => radial_t(paint, gx, gy),
 72	        _ => return,
 73	    };
 74	    if !t.is_finite() {
 75	        return;
 76	    }
 77	    let t = spread(t, paint.spread);
 78	    if t <= section[0].offset {
 79	        *rgba = section[0].rgba;
 80	        return;
 81	    }
 82	    let last = section.len() - 1;
 83	    if t >= section[last].offset {
 84	        *rgba = section[last].rgba;
 85	        return;
 86	    }
 87	    let mut right = 1;
 88	    while right < last && t > section[right].offset {
 89	        right += 1;
 90	    }
 91	    let left = right - 1;
 92	    let range = section[right].offset - section[left].offset;
 93	    let amount = if range <= 0.0 {
 94	        1.0
 95	    } else {
 96	        (t - section[left].offset) / range
 97	    };
 98	    let mut output = [0; 4];
 99	    for channel in 0..4 {
100	        output[channel] = ((1.0 - amount) * f64::from(section[left].rgba[channel])
101	            + amount * f64::from(section[right].rgba[channel]))
102	        .round()
103	        .clamp(0.0, 255.0) as u8;
104	    }
105	    *rgba = output;
106	}
107	
108	fn valid_stops(stops: &[PaintStop]) -> bool {
109	    stops.len() >= 2
110	        && stops
111	            .iter()
112	            .all(|stop| stop.offset.is_finite() && (0.0..=1.0).contains(&stop.offset))
113	        && stops
114	            .windows(2)
115	            .all(|pair| pair[1].offset >= pair[0].offset)
116	}
117	
118	fn spread(t: f64, spread: Spread) -> f64 {
119	    match spread {
120	        Spread::Pad => t,
121	        Spread::Repeat => t - t.floor(),
122	        Spread::Reflect => {
123	            let mut value = t % 2.0;
124	            if value < 0.0 {
125	                value += 2.0;
126	            }
127	            if value > 1.0 { 2.0 - value } else { value }
128	        }
129	    }
130	}
131	
132	fn radial_t(paint: &Paint, gx: f64, gy: f64) -> f64 {
133	    let (cx, cy, radius, fx, fy) = (
134	        paint.coordinates[0],
135	        paint.coordinates[1],
136	        paint.coordinates[2],
137	        paint.coordinates[3],
138	        paint.coordinates[4],
139	    );
140	    let (center_dx, center_dy, point_dx, point_dy) = (cx - fx, cy - fy, gx - fx, gy - fy);
141	    let a = center_dx * center_dx + center_dy * center_dy - radius * radius;
142	    let b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
143	    let c = point_dx * point_dx + point_dy * point_dy;
144	    if a.abs() <= 1e-15 {
145	        if b.abs() <= 1e-15 {
146	            return f64::NAN;
147	        }
148	        return -c / b;
149	    }
150	    let discriminant = b * b - 4.0 * a * c;
151	    if discriminant < 0.0 || !discriminant.is_finite() {
152	        return f64::NAN;
153	    }
154	    let root = discriminant.sqrt();
155	    let t0 = (-b - root) / (2.0 * a);
156	    let t1 = (-b + root) / (2.0 * a);
157	    let t = t0.max(t1);
158	    if t < 0.0 { t0.min(t1) } else { t }
159	}
