 46	fn key(definition: ElementId, viewport: [f64; 2], offset: usize) -> Result<Key> {
 47	    if definition.0 > u32::MAX as usize {
 48	        return Err(limit(LimitKind::PaintVisits, offset));
 49	    }
 50	    if !viewport
 51	        .into_iter()
 52	        .all(|value| value.is_finite() && value > 0.0)
 53	    {
 54	        return Err(unsupported(offset));
 55	    }
 56	    Ok(Key {
 57	        definition: definition.0 as u32,
 58	        width: viewport[0].to_bits(),
 59	        height: viewport[1].to_bits(),
 60	    })
 61	}
 62	
 63	fn hash(key: Key) -> usize {
 64	    let mut value =
 65	        u64::from(key.definition) ^ key.width ^ key.height.wrapping_add(0x9e37_79b9_7f4a_7c15);
 66	    value ^= value >> 30;
 67	    value = value.wrapping_mul(0xbf58_476d_1ce4_e5b9);
 68	    value ^= value >> 27;
 69	    value = value.wrapping_mul(0x94d0_49bb_1331_11eb);
 70	    value ^= value >> 31;
 71	    value as usize & (CACHE_SLOTS - 1)
 72	}
