 74	pub(crate) fn token_visit(
 75	    cache: &mut PaintCache,
 76	    control: &mut PaintControl<'_>,
 77	    offset: usize,
 78	) -> Result<()> {
 79	    let next = cache
 80	        .token_visits
 81	        .checked_add(1)
 82	        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
 83	    if next > MAX_TOKEN_VISITS {
 84	        return Err(limit(LimitKind::PaintVisits, offset));
 85	    }
 86	    control
 87	        .charge(WorkKind::TokenVisit, 1)
 88	        .map_err(|_| limit(LimitKind::Work, offset))?;
 89	    cache.token_visits = next;
 90	    Ok(())
 91	}
