192	/// Capacity leases remain in this source job until its cache and ledger end.
193	pub(crate) fn insert_template(
194	    cache: &mut PaintCache,
195	    source: &SourceOwner,
196	    definition: ElementId,
197	    viewport: [f64; 2],
198	    paint: Paint,
199	    stops: Vec<PaintStop>,
200	    stop_lease: vexel_scene::AllocationLease,
201	    control: &mut PaintControl<'_>,
202	    offset: usize,
203	) -> Result<usize> {
204	    let result = insert_inner(
205	        cache, source, definition, viewport, paint, stops, control, offset,
206	    );
207	    if result.is_err() {
208	        control.ledger.release(stop_lease)?;
