213	fn insert_inner(
214	    cache: &mut PaintCache,
215	    source: &SourceOwner,
216	    definition: ElementId,
217	    viewport: [f64; 2],
218	    paint: Paint,
219	    stops: Vec<PaintStop>,
220	    control: &mut PaintControl<'_>,
221	    offset: usize,
222	) -> Result<usize> {
223	    let wanted = key(definition, viewport, offset)?;
224	    if cache.entries.len() >= MAX_GRADIENTS {
225	        return Err(limit(LimitKind::PaintVisits, offset));
226	    }
227	    let mut old_stops = 0usize;
228	    for entry in &cache.entries {
229	        control
230	            .charge(WorkKind::PaintVisit, 1)
231	            .map_err(|_| limit(LimitKind::Work, offset))?;
232	        old_stops = old_stops
233	            .checked_add(entry.stops.len())
234	            .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
235	    }
236	    if stops.len() > MAX_GRADIENT_STOPS
237	        || old_stops > MAX_STOPS
238	        || stops.len() > MAX_STOPS - old_stops
239	    {
240	        return Err(limit(LimitKind::PaintStops, offset));
241	    }
242	    if !valid_stops(&stops)
243	        || paint.stops
244	            != (TableRange {
245	                first: 0,
246	                count: stops.len(),
247	            })
248	        || (!cache.slots.is_empty() && cache.slots.len() != CACHE_SLOTS)
249	    {
250	        return Err(invalid(offset));
251	    }
252	    let mut slot = hash(wanted);
253	    if !cache.slots.is_empty() {
254	        let mut available = false;
255	        for _ in 0..CACHE_SLOTS {
256	            probe(control, offset)?;
257	            if cache.slots[slot].is_none() {
258	                available = true;
259	                break;
260	            }
261	            slot = (slot + 1) & (CACHE_SLOTS - 1);
262	        }
263	        if !available {
264	            return Err(limit(LimitKind::PaintVisits, offset));
265	        }
266	    }
267	    let target_entries = if cache.entries.len() < cache.entries.capacity() {
268	        cache.entries.capacity()
269	    } else if cache.entries.capacity() == 0 {
270	        16
271	    } else {
272	        cache
273	            .entries
274	            .capacity()
275	            .checked_mul(2)
276	            .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?
277	            .min(MAX_GRADIENTS)
278	    };
279	    let mut slots = replacement(&cache.slots, CACHE_SLOTS, control, offset)?;
280	    let mut entries = match replacement(&cache.entries, target_entries, control, offset) {
281	        Ok(value) => value,
282	        Err(error) => {
283	            if let Some(buffer) = slots {
284	                control.ledger.release(buffer.lease)?;
285	            }
286	            return Err(error);
287	        }
288	    };
289	    // Every fallible control operation precedes cache mutation.
290	    let prepared = (|| {
291	        for bytes in [
292	            if slots.is_some() {
293	                cache
294	                    .slots
295	                    .len()
296	                    .checked_mul(std::mem::size_of::<Option<usize>>())
297	            } else {
298	                Some(0)
299	            },
300	            if entries.is_some() {
301	                cache
302	                    .entries
303	                    .len()
304	                    .checked_mul(std::mem::size_of::<GradientCacheEntry>())
305	            } else {
306	                Some(0)
307	            },
