 12	pub(crate) fn inherited_gradient_color(
 13	    shared: &mut DecodeSource<'_>,
 14	    gradient: ElementId,
 15	    cache: &mut vexel_scene::PaintCache,
 16	    control: &mut PaintControl<'_>,
 17	    offset: usize,
 18	) -> Result<Option<XmlSpan>> {
 19	    let tokens = shared.tokens();
 20	    let mut ancestors = [0usize; 64];
 21	    let mut count = 0;
 22	    for i in 0..=gradient.0 {
 23	        cache::token_visit(cache, control, offset)?;
 24	        let Some(token) = tokens.get(i) else {
 25	            return Err(invalid(offset));
 26	        };
 27	        if !matches!(
 28	            token.kind,
 29	            TokenKind::StartElement | TokenKind::EmptyElement
 30	        ) {
 31	            continue;
 32	        }
 33	        while count > 0 && tokens[ancestors[count - 1]].depth >= token.depth {
 34	            count -= 1;
 35	        }
 36	        if count == ancestors.len() {
 37	            return Err(limit(vexel_scene::LimitKind::Depth, offset));
 38	        }
 39	        ancestors[count] = i;
 40	        count += 1;
 41	    }
 42	    let mut parent: Option<CssPaint<'_>> = None;
 43	    for index in &ancestors[..count] {
 44	        let style = shared
 45	            .compute_style(ElementId(*index), parent.as_ref(), control)
 46	            .map_err(|error| remap(error, offset))?;
 47	        parent = Some(style);
 48	    }
 49	    Ok(parent.and_then(|style| style.value(Property::Color).map(|value| value.span)))
 50	}
