 52	pub(crate) fn collect_stops(
 53	    shared: &mut DecodeSource<'_>,
 54	    chain: &[ElementId],
 55	    cache: &mut vexel_scene::PaintCache,
 56	    control: &mut PaintControl<'_>,
 57	    offset: usize,
 58	) -> Result<(Vec<PaintStop>, usize, vexel_scene::AllocationLease)> {
 59	    for gradient in chain {
 60	        let inherited_color = inherited_gradient_color(shared, *gradient, cache, control, offset)?;
 61	        let end = element_end(shared.tokens(), gradient.0, cache, control, offset)?;
 62	        let mut values = [PaintStop {
 63	            offset: 0.0,
 64	            rgba: [0; 4],
 65	        }; MAX_GRADIENT_STOPS];
 66	        let mut count = 0;
 67	        let mut has_children = false;
 68	        for i in gradient.0.saturating_add(1)..end {
 69	            cache::token_visit(cache, control, offset)?;
 70	            let token = &shared.tokens()[i];
 71	            if !matches!(
 72	                token.kind,
 73	                TokenKind::StartElement | TokenKind::EmptyElement
 74	            ) || token.depth != shared.tokens()[gradient.0].depth + 1
 75	            {
 76	                continue;
 77	            }
 78	            has_children = true;
 79	            if token.prefix.length != 0 || !eq(shared.source(), token.local_name, b"stop") {
 80	                return Err(unsupported(offset));
 81	            }
 82	            if count == MAX_GRADIENT_STOPS {
 83	                return Err(limit(vexel_scene::LimitKind::PaintStops, offset));
 84	            }
 85	            let source = shared.source();
 86	            let tokens = shared.tokens();
 87	            let offset_span = attr(source, tokens, i, b"offset");
 88	            let color_span = attr(source, tokens, i, b"stop-color");
 89	            let opacity_span = attr(source, tokens, i, b"stop-opacity");
 90	            if let Some(style) = attr(source, tokens, i, b"style") {
 91	                if !supported_stop_inline_style(source, style) {
 92	                    return Err(unsupported(offset));
 93	                }
 94	            }
 95	            let computed = shared
 96	                .compute_style(ElementId(i), None, control)
 97	                .map_err(|error| remap(error, offset))?;
 98	            for property in Property::ALL {
 99	                if !matches!(
100	                    property,
101	                    Property::StopColor | Property::StopOpacity | Property::Color
102	                ) && computed.value(property).is_some()
103	                {
104	                    return Err(unsupported(offset));
105	                }
106	            }
107	            let computed_offset = computed
108	                .value(Property::StopColor)
109	                .map(|v| v.span)
110	                .or(color_span);
111	            let computed_opacity = computed
112	                .value(Property::StopOpacity)
113	                .map(|v| v.span)
114	                .or(opacity_span);
115	            let position = offset_span
116	                .filter(|span| span.length != 0)
117	                .map_or(Some(0.0), |v| number(shared.source(), v))
118	                .ok_or_else(|| unsupported(offset))?;
119	            let alpha = computed_opacity
120	                .map_or(Some(1.0), |v| number(shared.source(), v))
121	                .ok_or_else(|| unsupported(offset))?;
122	            if !(0.0..=1.0).contains(&position)
123	                || !(0.0..=1.0).contains(&alpha)
124	                || (count > 0 && position < values[count - 1].offset)
125	            {
126	                return Err(unsupported(offset));
127	            }
128	            let color = if let Some(span) = computed_offset {
129	                resolve_stop_color(
130	                    shared.source(),
131	                    span,
132	                    computed
133	                        .value(Property::Color)
134	                        .map(|v| v.span)
135	                        .or(inherited_color),
136	                )?
137	            } else {
138	                [0, 0, 0, 255]
139	            };
140	            values[count] = PaintStop {
141	                offset: position,
142	                rgba: [
143	                    color[0],
144	                    color[1],
145	                    color[2],
146	                    (f64::from(color[3]) * alpha).round().clamp(0.0, 255.0) as u8,
147	                ],
148	            };
149	            count += 1;
150	        }
151	        if count >= 2 {
152	            let requested = count
153	                .checked_mul(std::mem::size_of::<PaintStop>())
154	                .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
155	            if requested > control.ledger.available() {
156	                return Err(limit(vexel_scene::LimitKind::ReservedBytes, offset));
157	            }
158	            let mut owned = Vec::new();
159	            owned.try_reserve_exact(count).map_err(|_| oom(offset))?;
160	            let lease = control
161	                .ledger
162	                .admit_vec(vexel_scene::AllocationTag::None, &owned)?;
163	            let mut bytes = requested;
164	            while bytes != 0 {
165	                let batch = bytes.min(256);
166	                if vexel_base::WorkControl::charge(
167	                    control,
168	                    vexel_base::WorkKind::SourceRead,
169	                    batch as u64,
170	                )
171	                .is_err()
172	                {
173	                    control.ledger.release(lease)?;
174	                    return Err(limit(vexel_scene::LimitKind::Work, offset));
175	                }
176	                bytes -= batch;
177	            }
178	            owned.extend_from_slice(&values[..count]);
179	            return Ok((owned, count, lease));
180	        }
181	        if has_children {
182	            return Err(unsupported(offset));
183	        }
184	    }
185	    Err(unsupported(offset))
186	}
