256	pub(crate) fn read_coordinates(
257	    source: &[u8],
258	    tokens: &[XmlToken],
259	    chain: &[ElementId],
260	    viewport: [f64; 2],
261	    paint: &mut Paint,
262	    offset: usize,
263	) -> Result<()> {
264	    let linear = paint.kind == PaintKind::Linear;
265	    let names: [&[u8]; 5] = if linear {
266	        [b"x1", b"y1", b"x2", b"y2", b""]
267	    } else {
268	        [b"cx", b"cy", b"r", b"fx", b"fy"]
269	    };
270	    let diagonal = viewport[0].hypot(viewport[1]) / std::f64::consts::SQRT_2;
271	    if linear {
272	        paint.coordinates[2] = if paint.object_bounding_box {
273	            1.0
274	        } else {
275	            viewport[0]
276	        };
277	    } else {
278	        paint.coordinates[0] = if paint.object_bounding_box {
279	            0.5
280	        } else {
281	            viewport[0] * 0.5
282	        };
283	        paint.coordinates[1] = if paint.object_bounding_box {
284	            0.5
285	        } else {
286	            viewport[1] * 0.5
287	        };
288	        paint.coordinates[2] = if paint.object_bounding_box {
289	            0.5
290	        } else {
291	            diagonal * 0.5
292	        };
293	        paint.coordinates[3] = paint.coordinates[0];
294	        paint.coordinates[4] = paint.coordinates[1];
295	    }
296	    let count = if linear { 4 } else { 5 };
297	    let mut found = [false; 5];
298	    for coordinate in 0..count {
299	        for element in chain {
300	            let Some(value) = attr(source, tokens, element.0, names[coordinate]) else {
301	                continue;
302	            };
303	            found[coordinate] = true;
304	            let reference = if paint.object_bounding_box {
305	                1.0
306	            } else if linear {
307	                if coordinate % 2 == 0 {
308	                    viewport[0]
309	                } else {
310	                    viewport[1]
311	                }
312	            } else if coordinate == 2 {
313	                diagonal
314	            } else if coordinate == 0 || coordinate == 3 {
315	                viewport[0]
316	            } else {
317	                viewport[1]
318	            };
319	            if paint.object_bounding_box
320	                && value
321	                    .slice(source)
322	                    .is_some_and(|raw| raw.iter().any(|byte| byte.is_ascii_alphabetic()))
323	            {
324	                return Err(unsupported(offset));
325	            }
326	            let span = Span::from_offset_length(value.offset, value.length)
327	                .ok_or_else(|| invalid(offset))?;
328	            paint.coordinates[coordinate] =
329	                parse_length(source, span, reference).map_err(|_| unsupported(offset))?;
330	            break;
331	        }
332	    }
333	    if !linear {
334	        if !found[3] {
335	            paint.coordinates[3] = paint.coordinates[0];
336	        }
337	        if !found[4] {
338	            paint.coordinates[4] = paint.coordinates[1];
339	        }
340	        if paint.coordinates[2] <= 0.0 || !paint.coordinates[2].is_finite() {
341	            return Err(unsupported(offset));
342	        }
343	    }
344	    Ok(())
345	}
