347	fn supported_stop_inline_style(source: &[u8], span: XmlSpan) -> bool {
348	    let Some(bytes) = span.slice(source) else {
349	        return false;
350	    };
351	    let mut i = 0;
352	    while i < bytes.len() {
353	        while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\r' | b'\n' | b';') {
354	            i += 1;
355	        }
356	        if i == bytes.len() {
357	            break;
358	        }
359	        let start = i;
360	        while i < bytes.len() && bytes[i] != b':' && bytes[i] != b';' {
361	            i += 1;
362	        }
363	        if i == bytes.len() || bytes[i] != b':' {
364	            return false;
365	        }
366	        let mut end = i;
367	        while end > start && matches!(bytes[end - 1], b' ' | b'\t') {
368	            end -= 1;
369	        }
370	        if !matches!(
371	            &bytes[start..end],
372	            b"stop-color" | b"stop-opacity" | b"color"
373	        ) {
374	            return false;
375	        }
376	        i += 1;
377	        while i < bytes.len() && bytes[i] != b';' {
378	            i += 1;
379	        }
380	        if i < bytes.len() {
381	            i += 1;
382	        }
383	    }
384	    true
385	}
386	
387	fn resolve_stop_color(source: &[u8], stop: XmlSpan, current: Option<XmlSpan>) -> Result<[u8; 4]> {
388	    if !keyword(source, stop, b"currentColor") {
389	        return parse_css_color(source, stop);
390	    }
391	    let Some(color) = current else {
392	        return Ok([0, 0, 0, 255]);
393	    };
394	    if keyword(source, color, b"currentColor") {
395	        return Ok([0, 0, 0, 255]);
396	    }
397	    parse_css_color(source, color)
398	}
399	
400	fn parse_css_color(source: &[u8], span: XmlSpan) -> Result<[u8; 4]> {
401	    let base =
402	        Span::from_offset_length(span.offset, span.length).ok_or_else(|| invalid(span.offset))?;
403	    parse_color(source, base).ok_or_else(|| unsupported(span.offset))
404	}
405	
406	fn number(source: &[u8], span: XmlSpan) -> Option<f64> {
407	    let raw = span.slice(source)?;
408	    if raw.is_empty() || raw.len() >= 96 {
409	        return None;
410	    }
411	    let text = std::str::from_utf8(raw).ok()?;
412	    let text = text.trim_start_matches(|c| matches!(c, ' ' | '\t' | '\r' | '\n' | '\u{000c}'));
413	    let (numeric, percent) = text.strip_suffix('%').map_or((text, false), |v| (v, true));
414	    let value: f64 = numeric.parse().ok()?;
415	    if !value.is_finite() || value.abs() > 1_000_000.0 {
416	        return None;
417	    }
418	    Some(if percent { value / 100.0 } else { value })
419	}
420	
421	fn attr(source: &[u8], tokens: &[XmlToken], element: usize, name: &[u8]) -> Option<XmlSpan> {
422	    let mut i = element.checked_add(1)?;
423	    while tokens
424	        .get(i)
425	        .is_some_and(|token| token.kind == TokenKind::Attribute)
426	    {
427	        let token = &tokens[i];
428	        if token.prefix.length == 0 && eq(source, token.local_name, name) {
429	            return Some(token.value);
430	        }
431	        i += 1;
432	    }
433	    None
434	}

