132	struct TemplateResolution {
133	    index: usize,
134	    paint: Paint,
135	    template: GradientTemplateId,
136	}
137	
138	fn classify_inner(
139	    shared: &mut DecodeSource<'_>,
140	    value: XmlSpan,
141	    control: &mut PaintControl<'_>,
142	) -> Result<PaintReference> {
143	    let source = shared.source();
144	    let raw = value.slice(source).ok_or_else(|| invalid(value.offset))?;
145	    if raw.len() < 7 || !raw.starts_with(b"url(#") || raw.last() != Some(&b')') {
146	        return Err(unsupported(value.offset));
147	    }
148	    let id = XmlSpan {
149	        offset: value.offset + 5,
150	        length: value.length - 6,
151	    };
152	    if id.length == 0 {
153	        return Err(unsupported(value.offset));
154	    }
155	    let target = shared
156	        .find_reference(id, control)
157	        .map_err(|error| remap(error, value.offset))?
158	        .ok_or_else(|| unsupported(value.offset))?;
159	    let token = shared
160	        .tokens()
161	        .get(target.0)
162	        .ok_or_else(|| invalid(value.offset))?;
163	    if token.prefix.length != 0 {
164	        return Err(unsupported(value.offset));
165	    }
166	    if eq(source, token.local_name, b"linearGradient")
167	        || eq(source, token.local_name, b"radialGradient")
168	    {
169	        Ok(PaintReference::Gradient(target))
170	    } else if eq(source, token.local_name, b"pattern") {
171	        Ok(PaintReference::Pattern(target))
172	    } else {
173	        Err(unsupported(value.offset))
174	    }
175	}
176	
177	fn resolve_inner(
178	    shared: &mut DecodeSource<'_>,
179	    cache: &mut vexel_scene::PaintCache,
180	    value: XmlSpan,
181	    edges: &[Edge],
182	    user_inverse: Affine,
183	    viewport: [f64; 2],
184	    control: &mut PaintControl<'_>,
185	) -> Result<TemplateResolution> {
186	    control
187	        .checkpoint()
188	        .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
189	    let reference = classify_inner(shared, value, control)?;
190	    let PaintReference::Gradient(target) = reference else {
191	        return Err(unsupported(value.offset));
192	    };
193	    let target_token = shared
194	        .tokens()
195	        .get(target.0)
196	        .ok_or_else(|| invalid(value.offset))?;
197	    let linear = eq(shared.source(), target_token.local_name, b"linearGradient");
198	    let template_id = shared
199	        .gradient_template_id(target, viewport, control)
200	        .map_err(|error| remap(error, value.offset))?;
201	    let source_owner = Arc::clone(shared.source_owner());
202	
203	    if let Some(index) = cache::find_template(
204	        cache,
205	        &source_owner,
206	        target,
207	        viewport,
208	        if linear {
209	            PaintKind::Linear
210	        } else {
211	            PaintKind::Radial
212	        },
213	        control,
214	        value.offset,
215	    )? {
216	        let paint = bind_instance(
217	            cache.entries[index].paint,
218	            edges,
219	            user_inverse,
220	            value.offset,
221	            control,
222	        )?;
223	        control
224	            .checkpoint()
225	            .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
226	        return Ok(TemplateResolution {
227	            index,
228	            paint,
229	            template: template_id,
230	        });
231	    }
232	
233	    let mut chain = [ElementId(0); 16];
234	    let chain_count = collect_chain(
235	        shared,
236	        target,
237	        linear,
238	        &mut chain,
239	        cache,
240	        control,
241	        value.offset,
242	    )?;
243	    let kind = if linear {
244	        PaintKind::Linear
245	    } else {
246	        PaintKind::Radial
247	    };
248	    let mut definition = Paint {
249	        kind,
250	        spread: Spread::Pad,
251	        object_bounding_box: true,
252	        coordinates: [0.0; 6],
253	        bounds: [0.0; 4],
254	        user_inverse: affine_identity(),
255	        gradient_inverse: affine_identity(),
256	        stops: TableRange::EMPTY,
257	        pattern: None,
258	        pattern_inverse: affine_identity(),
259	        pattern_opacity: 1.0,
