312	fn bind_instance(
313	    mut paint: Paint,
314	    edges: &[Edge],
315	    inverse: Affine,
316	    offset: usize,
317	    control: &mut PaintControl<'_>,
318	) -> Result<Paint> {
319	    if edges.is_empty() {
320	        return Err(unsupported(offset));
321	    }
322	    let first = affine_map_point(inverse, edges[0].a).ok_or_else(|| unsupported(offset))?;
323	    let (mut min_x, mut min_y, mut max_x, mut max_y) = (first.x, first.y, first.x, first.y);
324	    for edge in edges {
325	        for point in [edge.a, edge.b] {
326	            control
327	                .charge(WorkKind::PaintVisit, 1)
328	                .map_err(|_| limit(vexel_scene::LimitKind::Work, offset))?;
329	            let p = affine_map_point(inverse, point).ok_or_else(|| unsupported(offset))?;
330	            min_x = min_x.min(p.x);
331	            min_y = min_y.min(p.y);
332	            max_x = max_x.max(p.x);
333	            max_y = max_y.max(p.y);
334	        }
335	    }
336	    paint.bounds = [min_x, min_y, max_x, max_y];
337	    paint.user_inverse = inverse;
338	    if paint.object_bounding_box && (max_x <= min_x || max_y <= min_y) {
339	        return Err(unsupported(offset));
340	    }
341	    Ok(paint)
342	}
343	
344	fn collect_chain(
345	    shared: &mut DecodeSource<'_>,
346	    target: ElementId,
347	    linear: bool,
348	    chain: &mut [ElementId; 16],
349	    cache: &mut vexel_scene::PaintCache,
350	    control: &mut PaintControl<'_>,
351	    offset: usize,
352	) -> Result<usize> {
353	    let source = shared.source();
354	    let tokens = shared.tokens();
355	    let mut count = 0;
356	    let mut current = target;
357	    loop {
358	        if count == chain.len() {
359	            return Err(limit(vexel_scene::LimitKind::Depth, offset));
360	        }
361	        let token = tokens.get(current.0).ok_or_else(|| invalid(offset))?;
362	        let is_linear = eq(source, token.local_name, b"linearGradient");
363	        let is_radial = eq(source, token.local_name, b"radialGradient");
364	        if (!is_linear && !is_radial) || is_linear != linear || token.prefix.length != 0 {
365	            return Err(unsupported(offset));
366	        }
367	        attributes_supported(source, tokens, current.0, linear, cache, control, offset)?;
368	        chain[count] = current;
369	        count += 1;
370	        let Some(href) = gradient_href(source, tokens, current.0, offset)? else {
371	            return Ok(count);
372	        };
373	        let id = XmlSpan {
374	            offset: href.offset + 1,
375	            length: href.length - 1,
376	        };
377	        let parent = shared
378	            .find_reference(id, control)
379	            .map_err(|error| remap(error, offset))?
380	            .ok_or_else(|| unsupported(offset))?;
381	        if chain[..count].contains(&parent) {
382	            return Err(unsupported(offset));
383	        }
384	        current = parent;
385	    }
386	}
387	
388	fn attributes_supported(
389	    source: &[u8],
390	    tokens: &[XmlToken],
391	    element: usize,
392	    linear: bool,
393	    cache: &mut vexel_scene::PaintCache,
394	    control: &mut PaintControl<'_>,
395	    offset: usize,
396	) -> Result<()> {
397	    let mut i = element
398	        .checked_add(1)
399	        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
400	    while tokens
401	        .get(i)
402	        .is_some_and(|token| token.kind == TokenKind::Attribute)
403	    {
404	        cache::token_visit(cache, control, offset)?;
405	        let token = &tokens[i];
406	        let name = token.local_name;
407	        let href = eq(source, name, b"href")
408	            && (token.prefix.length == 0
409	                || (eq(source, token.prefix, b"xlink")
410	                    && vexel_svg_reference::xlink_is_bound(source, tokens)));
411	        let common = token.prefix.length == 0
412	            && [
413	                b"id".as_slice(),
414	                b"class",
415	                b"style",
416	                b"gradientUnits",
417	                b"spreadMethod",
418	                b"gradientTransform",
419	            ]
420	            .iter()
421	            .any(|n| eq(source, name, n));
422	        let coordinates: &[&[u8]] = if linear {
423	            &[b"x1", b"y1", b"x2", b"y2"]
424	        } else {
425	            &[b"cx", b"cy", b"r", b"fx", b"fy"]
426	        };
427	        let coordinate =
428	            token.prefix.length == 0 && coordinates.iter().any(|n| eq(source, name, n));
429	        if !href && !common && !coordinate {
430	            return Err(unsupported(offset));
431	        }
432	        i += 1;
433	    }
434	    Ok(())
435	}
436	
437	fn gradient_href(
438	    source: &[u8],
439	    tokens: &[XmlToken],
440	    element: usize,
441	    offset: usize,
442	) -> Result<Option<XmlSpan>> {
443	    let mut found = None;
444	    let mut i = element
445	        .checked_add(1)
446	        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
447	    while tokens
448	        .get(i)
449	        .is_some_and(|token| token.kind == TokenKind::Attribute)
450	    {
451	        let token = &tokens[i];
452	        if eq(source, token.local_name, b"href") {
453	            let span = token.value;
454	            let raw = span.slice(source).ok_or_else(|| invalid(offset))?;
455	            if found.is_some()
456	                || (token.prefix.length != 0
457	                    && (!eq(source, token.prefix, b"xlink")
458	                        || !vexel_svg_reference::xlink_is_bound(source, tokens)))
459	                || raw.len() < 2
460	                || raw[0] != b'#'
461	            {
462	                return Err(unsupported(offset));
463	            }
464	            found = Some(span);
465	        }
466	        i += 1;
467	    }
468	    Ok(found)
469	}
470	
471	pub(crate) fn eq(source: &[u8], span: XmlSpan, text: &[u8]) -> bool {
472	    span.slice(source) == Some(text)
473	}
474	pub(crate) fn keyword(source: &[u8], span: XmlSpan, text: &[u8]) -> bool {
475	    vexel_svg_css::keyword_equals(source, span, text)
476	}
477	
478	pub(crate) fn remap(error: vexel_scene::Diagnostic, offset: usize) -> vexel_scene::Diagnostic {
479	    vexel_scene::Diagnostic { offset, ..error }
480	}

