 31	        return;
 32	    };
 33	    if paint.stops.count < 2 || paint.stops.count > MAX_GRADIENT_STOPS || end > stops.len() {
 34	        return;
 35	    }
 36	    let section = &stops[paint.stops.first..end];
 37	    if !valid_stops(section) {
