 49	        if !w.is_finite() || !h.is_finite() || w <= 0.0 || h <= 0.0 {
 50	            return;
 51	        }
 52	        gx = (local.x - paint.bounds[0]) / w;
 53	        gy = (local.y - paint.bounds[1]) / h;
 54	    }
 55	    let Some(point) = affine_map_point(paint.gradient_inverse, Point { x: gx, y: gy }) else {
 56	        return;
 57	    };
 58	    gx = point.x;
 59	    gy = point.y;
