 61	        PaintKind::Linear => {
 62	            let dx = paint.coordinates[2] - paint.coordinates[0];
 63	            let dy = paint.coordinates[3] - paint.coordinates[1];
 64	            let length = dx * dx + dy * dy;
 65	            if length == 0.0 {
 66	                1.0
 67	            } else {
 68	                ((gx - paint.coordinates[0]) * dx + (gy - paint.coordinates[1]) * dy) / length
 69	            }
 70	        }
 71	        PaintKind::Radial => radial_t(paint, gx, gy),
 72	        _ => return,
 73	    };
 74	    if !t.is_finite() {
 75	        return;
 76	    }
 77	    let t = spread(t, paint.spread);
