 79	        *rgba = section[0].rgba;
 80	        return;
 81	    }
 82	    let last = section.len() - 1;
 83	    if t >= section[last].offset {
 84	        *rgba = section[last].rgba;
 85	        return;
 86	    }
 87	    let mut right = 1;
 88	    while right < last && t > section[right].offset {
 89	        right += 1;
 90	    }
 91	    let left = right - 1;
 92	    let range = section[right].offset - section[left].offset;
