118	fn spread(t: f64, spread: Spread) -> f64 {
119	    match spread {
120	        Spread::Pad => t,
121	        Spread::Repeat => t - t.floor(),
122	        Spread::Reflect => {
123	            let mut value = t % 2.0;
124	            if value < 0.0 {
125	                value += 2.0;
126	            }
127	            if value > 1.0 { 2.0 - value } else { value }
