132	fn radial_t(paint: &Paint, gx: f64, gy: f64) -> f64 {
133	    let (cx, cy, radius, fx, fy) = (
134	        paint.coordinates[0],
135	        paint.coordinates[1],
136	        paint.coordinates[2],
137	        paint.coordinates[3],
138	        paint.coordinates[4],
139	    );
140	    let (center_dx, center_dy, point_dx, point_dy) = (cx - fx, cy - fy, gx - fx, gy - fy);
141	    let a = center_dx * center_dx + center_dy * center_dy - radius * radius;
142	    let b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
143	    let c = point_dx * point_dx + point_dy * point_dy;
144	    if a.abs() <= 1e-15 {
145	        if b.abs() <= 1e-15 {
146	            return f64::NAN;
147	        }
148	        return -c / b;
149	    }
150	    let discriminant = b * b - 4.0 * a * c;
151	    if discriminant < 0.0 || !discriminant.is_finite() {
152	        return f64::NAN;
153	    }
154	    let root = discriminant.sqrt();
155	    let t0 = (-b - root) / (2.0 * a);
156	    let t1 = (-b + root) / (2.0 * a);
157	    let t = t0.max(t1);
158	    if t < 0.0 { t0.min(t1) } else { t }
