 93	pub(crate) fn probe(control: &mut PaintControl<'_>, offset: usize) -> Result<()> {
 94	    control
 95	        .charge(WorkKind::ReferenceProbe, 1)
 96	        .map_err(|_| limit(LimitKind::Work, offset))
 97	}
