107	fn entry_valid(
108	    entry: &GradientCacheEntry,
109	    source: &SourceOwner,
110	    key: Key,
111	    kind: PaintKind,
112	) -> bool {
113	    let context = entry.context;
114	    entry.definition.0 == key.definition as usize
115	        && Arc::ptr_eq(&entry.source, source)
116	        && context.viewport.map(f64::to_bits) == [key.width, key.height]
117	        && context.user_inverse == affine_identity()
118	        && context.bounds == [0.0; 4]
119	        && entry.stop_range == entry.paint.stops
120	        && entry.paint.user_inverse == affine_identity()
121	        && entry.paint.bounds == [0.0; 4]
122	        && affine_valid(entry.paint.gradient_inverse)
123	        && entry.paint.coordinates.into_iter().all(f64::is_finite)
124	        && (entry.paint.kind != PaintKind::Radial || entry.paint.coordinates[2] > 0.0)
125	        && entry.paint.pattern.is_none()
126	        && entry
127	            .stop_range
128	            .slice(&entry.stops)
129	            .is_some_and(valid_stops)
130	        && entry.stops.len() <= MAX_GRADIENT_STOPS
131	        && entry.paint.kind == kind
132	}
133	
134	fn valid_stops(stops: &[PaintStop]) -> bool {
135	    stops.len() >= 2
136	        && stops
137	            .iter()
138	            .all(|stop| stop.offset.is_finite() && (0.0..=1.0).contains(&stop.offset))
139	        && stops
140	            .windows(2)
141	            .all(|pair| pair[1].offset >= pair[0].offset)
142	}
