144	/// Find a source-owned template, validating every slot before indexing. The
145	/// cache is the accepted scene contract; there is no paint-local replacement.
146	pub(crate) fn find_template(
147	    cache: &PaintCache,
148	    source: &SourceOwner,
149	    definition: ElementId,
150	    viewport: [f64; 2],
151	    kind: PaintKind,
152	    control: &mut PaintControl<'_>,
153	    offset: usize,
154	) -> Result<Option<usize>> {
155	    if cache.entries.len() > MAX_GRADIENTS
156	        || cache.slots.len() > CACHE_SLOTS
157	        || cache.token_visits > MAX_TOKEN_VISITS
158	        || (!cache.entries.is_empty() && cache.slots.len() != CACHE_SLOTS)
159	    {
160	        return Err(limit(LimitKind::PaintVisits, offset));
161	    }
162	    let wanted = key(definition, viewport, offset)?;
163	    if cache.slots.is_empty() {
164	        return Ok(None);
165	    }
166	    let mut slot = hash(wanted);
167	    for _ in 0..CACHE_SLOTS {
168	        probe(control, offset)?;
169	        match cache.slots.get(slot).copied().flatten() {
170	            None => return Ok(None),
171	            Some(index) => {
172	                let entry = cache.entries.get(index).ok_or_else(|| invalid(offset))?;
173	                if !Arc::ptr_eq(&entry.source, source) {
174	                    return Err(invalid(offset));
175	                }
176	                let candidate = key(entry.definition, entry.context.viewport, offset)
177	                    .map_err(|_| invalid(offset))?;
178	                if candidate == wanted && Arc::ptr_eq(&entry.source, source) {
179	                    if !entry_valid(entry, source, wanted, kind) {
180	                        return Err(invalid(offset));
181	                    }
182	                    return Ok(Some(index));
183	                }
184	            }
185	        }
186	        slot = (slot + 1) & (CACHE_SLOTS - 1);
187	    }
188	    Ok(None)
189	}
