352	static bool parse_stops(svg_css_sheet *css, base_bytes source,
353	                        const svg_xml_token *tokens, size_t count,
354	                        size_t gradient, const svg_css_paint *gradient_style,
355	                        size_t *token_visits,
356	                        svg_paint_stop stops[SVG_PAINT_MAX_GRADIENT_STOPS],
357	                        size_t *stop_count, bool *has_stop_elements,
358	                        bool *hit_limit, bool *hit_oom)
359	{
360	    *has_stop_elements = false;
361	    *hit_limit = false;
362	    *hit_oom = false;
363	    size_t end = gradient;
364	    if (!element_end(tokens, count, gradient, token_visits, &end)) {
365	        *hit_limit = true;
366	        return false;
367	    }
368	    size_t n = 0U;
369	    for (size_t i = gradient + 1U; i < end; ++i) {
370	        if (!count_token_visit(token_visits)) {
371	            *hit_limit = true;
372	            return false;
373	        }
374	        if ((tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
375	             tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) ||
376	            tokens[i].depth != tokens[gradient].depth + 1U) continue;
377	        *has_stop_elements = true;
378	        if (!eq(source, tokens[i].local_name, "stop") ||
379	            tokens[i].prefix.length != 0U) return false;
380	        if (n == SVG_PAINT_MAX_GRADIENT_STOPS) { *hit_limit = true; return false; }
381	        svg_xml_span offset = {0}, stop_color = {0}, opacity = {0}, style = {0};
382	        (void)attr(source, tokens, count, i, "offset", &offset);
383	        if (attr(source, tokens, count, i, "style", &style) &&
384	            !supported_stop_inline_style(source, style)) return false;
385	        svg_css_paint computed;
386	        svg_css_error css_error = svg_css_compute(css, source, tokens, count, i,
387	                                                 gradient_style, &computed);
388	        if (css_error != SVG_CSS_OK) {
389	            *hit_limit = css_error == SVG_CSS_LIMIT;
390	            *hit_oom = css_error == SVG_CSS_OOM;
391	            return false;
392	        }
393	        for (size_t property = 0U; property < SVG_CSS_PROPERTY_COUNT; ++property) {
394	            if (property != SVG_CSS_STOP_COLOR &&
395	                property != SVG_CSS_STOP_OPACITY && property != SVG_CSS_COLOR &&
396	                computed.values[property].present) return false;
397	        }
398	        bool has_stop_color = svg_css_paint_value(
399	            &computed, SVG_CSS_STOP_COLOR, &stop_color);
400	        bool has_opacity = svg_css_paint_value(
401	            &computed, SVG_CSS_STOP_OPACITY, &opacity);
402	        double position = 0.0, alpha = 1.0;
403	        if (offset.length != 0U && !number(source, offset, &position)) return false;
404	        if (has_opacity && !number(source, opacity, &alpha)) return false;
405	        if (position < 0.0 || position > 1.0 || alpha < 0.0 || alpha > 1.0 ||
406	            (n != 0U && position < stops[n - 1U].offset)) return false;
407	        if (!has_stop_color) {
408	            stops[n].rgba[0] = stops[n].rgba[1] = stops[n].rgba[2] = 0U;
409	            stops[n].rgba[3] = 255U;
410	        } else if (stop_color.length == 0U ||
411	                   !resolve_stop_color(source, stop_color, &computed,
412	                                       stops[n].rgba))
413	            return false;
414	        stops[n].offset = position;
415	        stops[n].rgba[3] = (uint8_t)lround((double)stops[n].rgba[3] * alpha);
416	        ++n;
417	        if (tokens[i].kind == SVG_XML_TOKEN_START_ELEMENT) {
418	            size_t stop_end = i;
419	            if (!element_end(tokens, count, i, token_visits, &stop_end)) {
420	                *hit_limit = true;
421	                return false;
422	            }
423	            i = stop_end;
424	        }
425	    }
426	    if (n < 2U) return false;
427	    *stop_count = n;
428	    return true;
429	}
