431	static bool gradient_coordinates(base_bytes source, const svg_xml_token *tokens,
432	                                 size_t count, const size_t *chain,
433	                                 size_t chain_count, bool object_box,
434	                                 double viewport_width, double viewport_height,
435	                                 svg_shape_paint *paint)
436	{
437	    static const char *const linear_names[4] = {"x1", "y1", "x2", "y2"};
438	    static const char *const radial_names[5] = {"cx", "cy", "r", "fx", "fy"};
439	    const char *const *names = paint->kind == SVG_SHAPE_PAINT_LINEAR ?
440	        linear_names : radial_names;
441	    double diagonal = hypot(viewport_width, viewport_height) / sqrt(2.0);
442	    double defaults[5] = {0.0};
443	    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
444	        defaults[2] = object_box ? 1.0 : viewport_width;
445	    } else {
446	        defaults[0] = object_box ? 0.5 : viewport_width * 0.5;
447	        defaults[1] = object_box ? 0.5 : viewport_height * 0.5;
448	        defaults[2] = object_box ? 0.5 : diagonal * 0.5;
449	        defaults[3] = defaults[0];
450	        defaults[4] = defaults[1];
451	    }
452	    size_t coordinate_count = paint->kind == SVG_SHAPE_PAINT_LINEAR ? 4U : 5U;
453	    bool coordinate_found[5] = {false, false, false, false, false};
454	    for (size_t coordinate = 0U; coordinate < coordinate_count; ++coordinate) {
455	        paint->coordinates[coordinate] = defaults[coordinate];
456	        for (size_t definition = 0U; definition < chain_count; ++definition) {
457	            svg_xml_span value;
458	            if (!attr(source, tokens, count, chain[definition],
459	                      names[coordinate], &value)) continue;
460	            coordinate_found[coordinate] = true;
461	            double reference = object_box ? 1.0 :
462	                (paint->kind == SVG_SHAPE_PAINT_LINEAR ?
463	                    ((coordinate & 1U) == 0U ? viewport_width : viewport_height) :
464	                    coordinate == 2U ? diagonal :
465	                    (coordinate == 0U || coordinate == 3U ?
466	                        viewport_width : viewport_height));
467	            if (object_box) {
468	                size_t end = value.offset + value.length;
469	                for (size_t at = value.offset; at < end; ++at) {
470	                    uint8_t byte = source.ptr[at];
471	                    if ((byte >= 'a' && byte <= 'z') ||
472	                        (byte >= 'A' && byte <= 'Z')) return false;
473	                }
474	            }
475	            if (!svg_shape_read_length(source, value, reference,
476	                                       &paint->coordinates[coordinate]))
477	                return false;
478	            break;
479	        }
480	    }
481	    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[3]) paint->coordinates[3] = paint->coordinates[0];
482	    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[4]) paint->coordinates[4] = paint->coordinates[1];
483	    return paint->kind != SVG_SHAPE_PAINT_RADIAL ||
484	           (paint->coordinates[2] > 0.0 && isfinite(paint->coordinates[2]));
485	}
