487	static bool collect_gradient_chain(base_bytes source,
488	                                   const svg_xml_token *tokens,
489	                                   size_t token_count,
490	                                   svg_reference_index *references,
491	                                   size_t target, bool linear,
492	                                   size_t *token_visits, size_t chain[16],
493	                                   size_t *chain_count, bool *hit_limit)
494	{
495	    *chain_count = 0U;
496	    *hit_limit = false;
497	    size_t current = target;
498	    while (true) {
499	        if (*chain_count == 16U) {
500	            *hit_limit = true;
501	            return false;
502	        }
503	        bool current_linear = eq(source, tokens[current].local_name,
504	                                 "linearGradient");
505	        bool current_radial = eq(source, tokens[current].local_name,
506	                                 "radialGradient");
507	        if ((!current_linear && !current_radial) || current_linear != linear ||
508	            tokens[current].prefix.length != 0U) return false;
509	        bool attr_limit = false;
510	        if (!gradient_attributes_supported(source, tokens, token_count,
511	                current, linear, token_visits, &attr_limit)) {
512	            *hit_limit = attr_limit;
513	            return false;
514	        }
515	        chain[(*chain_count)++] = current;
516	        bool has_href = false;
517	        svg_xml_span href = {0};
518	        if (!gradient_href(source, tokens, token_count, current,
519	                           &has_href, &href)) return false;
520	        if (!has_href) return true;
521	        svg_xml_span id = {href.offset + 1U, href.length - 1U};
522	        size_t parent;
523	        if (!svg_reference_index_find(source, tokens, token_count,
524	                                      references, id, &parent)) return false;
525	        for (size_t i = 0U; i < *chain_count; ++i)
526	            if (chain[i] == parent) return false;
527	        current = parent;
528	    }
529	}
