531	svg_shape_error svg_paint_resolve_fill(base_bytes source,
532	                                       const svg_xml_token *tokens,
533	                                       size_t token_count,
534	                                       svg_reference_index *references,
535	                                       svg_css_sheet *css,
536	                                       svg_paint_cache **cache,
537	                                       size_t *token_visits,
538	                                       svg_xml_span fill,
539	                                       const geom_edge *edges, size_t edge_count,
540	                                       geom_affine user_inverse,
541	                                       double viewport_width, double viewport_height,
542	                                       svg_shape_paint *paint,
543	                                       svg_paint_stop **stops,
544	                                       size_t *stop_count,
545	                                       svg_shape_diagnostic *diagnostic)
546	{
547	    if (cache == NULL || stops == NULL || stop_count == NULL || paint == NULL) {
548	        if (diagnostic != NULL)
549	            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_INVALID_ARGUMENT,
550	                                                 fill.offset};
551	        return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
552	    }
553	    if (fill.length < 7U || fill.offset > source.len ||
554	        fill.length > source.len - fill.offset ||
555	        memcmp(source.ptr + fill.offset, "url(#", 5U) != 0 ||
556	        source.ptr[fill.offset + fill.length - 1U] != ')') return SVG_SHAPE_ERROR_UNSUPPORTED;
557	    svg_xml_span target_id = {fill.offset + 5U, fill.length - 6U};
558	    size_t target;
559	    if (!svg_reference_index_find(source, tokens, token_count, references,
560	                                  target_id, &target)) goto unsupported;
561	    if (target > UINT32_MAX) goto limit;
562	    bool linear = eq(source, tokens[target].local_name, "linearGradient");
563	    bool radial = eq(source, tokens[target].local_name, "radialGradient");
564	    if ((!linear && !radial) || tokens[target].prefix.length != 0U)
565	        goto unsupported;
566	
567	    svg_cached_gradient *cached = cache_find(*cache, (uint32_t)target,
568	                                             viewport_width,
569	                                             viewport_height);
570	    if (cached == NULL) {
571	        svg_shape_error cache_error = cache_create(cache);
572	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
573	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
574	
575	        size_t chain[16], chain_count = 0U;
576	        bool chain_limit = false;
577	        if (!collect_gradient_chain(source, tokens, token_count, references,
578	                target, linear, token_visits, chain, &chain_count,
579	                &chain_limit)) {
580	            if (chain_limit) goto limit;
581	            goto unsupported;
582	        }
583	        svg_shape_paint definition = {0};
584	        definition.kind = linear ? SVG_SHAPE_PAINT_LINEAR :
585	                                   SVG_SHAPE_PAINT_RADIAL;
586	        definition.object_bounding_box = true;
587	        definition.spread_method = SVG_SHAPE_SPREAD_PAD;
588	        definition.gradient_inverse = geom_affine_identity();
589	        bool found_units = false, found_spread = false, found_transform = false;
590	        for (size_t i = 0U; i < chain_count; ++i) {
591	            svg_xml_span value;
592	            if (!found_units && attr(source, tokens, token_count, chain[i],
593	                                     "gradientUnits", &value)) {
594	                if (eq(source, value, "userSpaceOnUse"))
595	                    definition.object_bounding_box = false;
596	                else if (!eq(source, value, "objectBoundingBox"))
597	                    goto unsupported;
598	                found_units = true;
599	            }
600	            if (!found_spread && attr(source, tokens, token_count, chain[i],
601	                                      "spreadMethod", &value)) {
602	                if (eq(source, value, "reflect"))
603	                    definition.spread_method = SVG_SHAPE_SPREAD_REFLECT;
604	                else if (eq(source, value, "repeat"))
605	                    definition.spread_method = SVG_SHAPE_SPREAD_REPEAT;
606	                else if (!eq(source, value, "pad"))
607	                    goto unsupported;
608	                found_spread = true;
609	            }
610	            if (!found_transform && attr(source, tokens, token_count, chain[i],
611	                                         "gradientTransform", &value)) {
612	                geom_affine transform;
613	                size_t operations = 0U;
614	                if (!svg_shape_transform_parse(source, value, &transform,
615	                                               &operations) ||
616	                    !svg_shape_affine_inverse(transform,
617	                                              &definition.gradient_inverse))
618	                    goto unsupported;
619	                (void)operations;
620	                found_transform = true;
621	            }
622	        }
623	        if (!gradient_coordinates(source, tokens, token_count, chain,
624	                chain_count, definition.object_bounding_box, viewport_width,
625	                viewport_height, &definition)) goto unsupported;
626	
627	        svg_paint_stop local[SVG_PAINT_MAX_GRADIENT_STOPS];
628	        size_t local_count = 0U;
629	        bool inherited_stops = false;
630	        for (size_t i = 0U; i < chain_count; ++i) {
631	            svg_css_paint parent_color = {0};
632	            svg_css_error css_error = gradient_inherited_color(
633	                css, source, tokens, token_count, chain[i], token_visits,
634	                &parent_color);
635	            if (css_error == SVG_CSS_LIMIT) goto limit;
636	            if (css_error == SVG_CSS_OOM) goto oom;
637	            if (css_error != SVG_CSS_OK) goto unsupported;
638	            bool has_stop_elements = false, stop_limit = false, stop_oom = false;
639	            if (parse_stops(css, source, tokens, token_count, chain[i],
640	                    &parent_color, token_visits, local, &local_count,
641	                    &has_stop_elements, &stop_limit, &stop_oom)) {
642	                inherited_stops = true;
643	                break;
644	            }
645	            if (stop_limit) goto limit;
646	            if (stop_oom) goto oom;
647	            if (has_stop_elements) goto unsupported;
648	        }
649	        if (!inherited_stops) goto unsupported;
650	        if (*stop_count > SVG_PAINT_MAX_STOPS ||
651	            local_count > SVG_PAINT_MAX_STOPS - *stop_count) goto limit;
652	        cache_error = cache_reserve_entry(*cache);
653	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
654	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
655	        size_t new_stop_count = *stop_count + local_count;
656	        if (new_stop_count > SIZE_MAX / sizeof(**stops)) goto limit;
657	        svg_paint_stop *grown = svg_shape_realloc(
658	            *stops, new_stop_count * sizeof(**stops));
659	        if (grown == NULL) goto oom;
660	        size_t first_stop = *stop_count;
661	        memcpy(grown + first_stop, local, local_count * sizeof(*local));
662	        *stops = grown;
663	        *stop_count = new_stop_count;
664	
665	        svg_cached_gradient pending = {0};
666	        pending.token_index = (uint32_t)target;
667	        pending.viewport_width = viewport_width;
668	        pending.viewport_height = viewport_height;
669	        pending.kind = definition.kind;
670	        pending.spread_method = definition.spread_method;
671	        pending.object_bounding_box = definition.object_bounding_box;
672	        memcpy(pending.coordinates, definition.coordinates,
673	               sizeof(pending.coordinates));
674	        pending.gradient_inverse = definition.gradient_inverse;
675	        pending.first_stop = first_stop;
676	        pending.stop_count = local_count;
677	        cache_error = cache_insert(*cache, &pending, &cached);
678	        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
679	        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
680	    }
681	
682	    svg_shape_paint result = {0};
683	    result.kind = cached->kind;
684	    result.spread_method = cached->spread_method;
685	    result.object_bounding_box = cached->object_bounding_box;
686	    memcpy(result.coordinates, cached->coordinates, sizeof(result.coordinates));
687	    result.first_stop = cached->first_stop;
688	    result.stop_count = cached->stop_count;
689	    result.user_inverse = user_inverse;
690	    result.gradient_inverse = cached->gradient_inverse;
691	    if (edge_count == 0U) goto unsupported;
692	    geom_point first_local;
693	    if (!geom_affine_map_point(user_inverse, edges[0].a, &first_local))
694	        goto unsupported;
695	    double min_x = first_local.x, min_y = first_local.y;
696	    double max_x = min_x, max_y = min_y;
697	    for (size_t i = 0U; i < edge_count; ++i) {
698	        const geom_point source_points[2] = {edges[i].a, edges[i].b};
699	        for (size_t j = 0U; j < 2U; ++j) {
700	            geom_point point;
701	            if (!geom_affine_map_point(user_inverse, source_points[j], &point))
702	                goto unsupported;
703	            if (point.x < min_x) min_x = point.x;
704	            if (point.x > max_x) max_x = point.x;
705	            if (point.y < min_y) min_y = point.y;
706	            if (point.y > max_y) max_y = point.y;
707	        }
708	    }
709	    result.bounds[0] = min_x; result.bounds[1] = min_y;
710	    result.bounds[2] = max_x; result.bounds[3] = max_y;
711	    if (result.object_bounding_box && (max_x <= min_x || max_y <= min_y)) goto unsupported;
712	    *paint = result;
713	    return SVG_SHAPE_ERROR_NONE;
714	limit:
715	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, fill.offset};
716	    return SVG_SHAPE_ERROR_LIMIT;
717	oom:
718	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, fill.offset};
719	    return SVG_SHAPE_ERROR_OOM;
720	unsupported:
721	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_UNSUPPORTED, fill.offset};
722	    return SVG_SHAPE_ERROR_UNSUPPORTED;
723	}
