725	void svg_paint_sample(const svg_shape_paint *paint, const svg_paint_stop *stops,
726	                      double x, double y, uint8_t rgba[4])
727	{
728	    if (paint == NULL || stops == NULL || paint->stop_count < 2U) return;
729	    geom_point local;
730	    if (!geom_affine_map_point(paint->user_inverse, (geom_point){x, y}, &local))
731	        return;
732	    double gx = local.x, gy = local.y, t;
733	    if (paint->object_bounding_box) {
734	        gx = (local.x - paint->bounds[0]) /
735	             (paint->bounds[2] - paint->bounds[0]);
736	        gy = (local.y - paint->bounds[1]) /
737	             (paint->bounds[3] - paint->bounds[1]);
738	    }
739	    geom_point transformed;
740	    if (!geom_affine_map_point(paint->gradient_inverse,
741	                               (geom_point){gx, gy}, &transformed)) return;
742	    gx = transformed.x;
743	    gy = transformed.y;
744	    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
745	        double dx = paint->coordinates[2] - paint->coordinates[0];
746	        double dy = paint->coordinates[3] - paint->coordinates[1];
747	        double length = dx * dx + dy * dy;
748	        t = length == 0.0 ? 1.0 : ((gx - paint->coordinates[0]) * dx +
749	                                   (gy - paint->coordinates[1]) * dy) / length;
750	    } else {
751	        double focal_x = paint->coordinates[3];
752	        double focal_y = paint->coordinates[4];
753	        double center_dx = paint->coordinates[0] - focal_x;
754	        double center_dy = paint->coordinates[1] - focal_y;
755	        double point_dx = gx - focal_x;
756	        double point_dy = gy - focal_y;
757	        double radius = paint->coordinates[2];
758	        double a = center_dx * center_dx + center_dy * center_dy -
759	                   radius * radius;
760	        double b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
761	        double c = point_dx * point_dx + point_dy * point_dy;
762	        if (fabs(a) <= 1e-15) {
763	            if (fabs(b) <= 1e-15) return;
764	            t = -c / b;
765	        } else {
766	            double discriminant = b * b - 4.0 * a * c;
767	            if (discriminant < 0.0 || !isfinite(discriminant)) return;
768	            double root = sqrt(discriminant);
769	            double t0 = (-b - root) / (2.0 * a);
770	            double t1 = (-b + root) / (2.0 * a);
771	            t = fmax(t0, t1);
772	            if (t < 0.0) t = fmin(t0, t1);
773	        }
774	    }
775	    if (!isfinite(t)) return;
776	    if (paint->spread_method == SVG_SHAPE_SPREAD_REPEAT) {
777	        t -= floor(t);
778	    } else if (paint->spread_method == SVG_SHAPE_SPREAD_REFLECT) {
779	        t = fmod(t, 2.0);
780	        if (t < 0.0) t += 2.0;
781	        if (t > 1.0) t = 2.0 - t;
782	    }
783	    if (t <= stops[paint->first_stop].offset) {
784	        memcpy(rgba, stops[paint->first_stop].rgba, 4U);
785	        return;
786	    }
787	    size_t last = paint->first_stop + paint->stop_count - 1U;
788	    if (t >= stops[last].offset) {
789	        memcpy(rgba, stops[last].rgba, 4U);
790	        return;
791	    }
792	    size_t right = paint->first_stop + 1U;
793	    while (right <= last && t > stops[right].offset) ++right;
794	    size_t left = right - 1U;
795	    double range = stops[right].offset - stops[left].offset;
796	    double amount = range <= 0.0 ? 1.0 : (t - stops[left].offset) / range;
797	    for (size_t c = 0U; c < 4U; ++c)
798	        rgba[c] = (uint8_t)lround((1.0 - amount) * stops[left].rgba[c] + amount * stops[right].rgba[c]);
799	}
