 20	/// Classify a local paint-server URL for the gradient resolver or definition
 21	/// planner. Patterns are returned explicitly and are never treated as solids.
 22	pub fn classify_fill(
 23	    ctx: &mut ResolveContext<'_, '_>,
 24	    value: XmlSpan,
 25	    control: &mut dyn WorkControl,
 26	) -> Result<PaintReference> {
 27	    ctx.validate().map_err(|error| remap(error, value.offset))?;
 28	    let ResolveContext {
 29	        shared,
 30	        cache: _,
 31	        ledger,
 32	    } = ctx;
 33	    let mut control = PaintControl::new(ledger, control);
 34	    let result = classify_inner(shared, value, &mut control);
 35	    control.result_at(result, value.offset)
 36	}
