312	fn bind_instance(
313	    mut paint: Paint,
314	    edges: &[Edge],
315	    inverse: Affine,
316	    offset: usize,
317	    control: &mut PaintControl<'_>,
318	) -> Result<Paint> {
319	    if edges.is_empty() {
320	        return Err(unsupported(offset));
321	    }
322	    let first = affine_map_point(inverse, edges[0].a).ok_or_else(|| unsupported(offset))?;
323	    let (mut min_x, mut min_y, mut max_x, mut max_y) = (first.x, first.y, first.x, first.y);
324	    for edge in edges {
325	        for point in [edge.a, edge.b] {
326	            control
327	                .charge(WorkKind::PaintVisit, 1)
328	                .map_err(|_| limit(vexel_scene::LimitKind::Work, offset))?;
329	            let p = affine_map_point(inverse, point).ok_or_else(|| unsupported(offset))?;
330	            min_x = min_x.min(p.x);
331	            min_y = min_y.min(p.y);
332	            max_x = max_x.max(p.x);
333	            max_y = max_y.max(p.y);
334	        }
335	    }
336	    paint.bounds = [min_x, min_y, max_x, max_y];
337	    paint.user_inverse = inverse;
338	    if paint.object_bounding_box && (max_x <= min_x || max_y <= min_y) {
339	        return Err(unsupported(offset));
340	    }
341	    Ok(paint)
342	}
