437	fn gradient_href(
438	    source: &[u8],
439	    tokens: &[XmlToken],
440	    element: usize,
441	    offset: usize,
442	) -> Result<Option<XmlSpan>> {
443	    let mut found = None;
444	    let mut i = element
445	        .checked_add(1)
446	        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
447	    while tokens
448	        .get(i)
449	        .is_some_and(|token| token.kind == TokenKind::Attribute)
450	    {
451	        let token = &tokens[i];
452	        if eq(source, token.local_name, b"href") {
453	            let span = token.value;
454	            let raw = span.slice(source).ok_or_else(|| invalid(offset))?;
455	            if found.is_some()
456	                || (token.prefix.length != 0
457	                    && (!eq(source, token.prefix, b"xlink")
458	                        || !vexel_svg_reference::xlink_is_bound(source, tokens)))
459	                || raw.len() < 2
460	                || raw[0] != b'#'
461	            {
462	                return Err(unsupported(offset));
463	            }
464	            found = Some(span);
465	        }
466	        i += 1;
467	    }
468	    Ok(found)
469	}
