362	struct Replacement<T> {
363	    values: Vec<T>,
364	    lease: vexel_scene::AllocationLease,
365	    old_bytes: usize,
366	    new_bytes: usize,
367	}
368	
369	fn replacement<T>(
370	    old: &Vec<T>,
371	    target: usize,
372	    control: &mut PaintControl<'_>,
373	    offset: usize,
374	) -> Result<Option<Replacement<T>>> {
375	    if old.capacity() >= target {
376	        return Ok(None);
377	    }
378	    let size = std::mem::size_of::<T>();
379	    let requested = target
380	        .checked_mul(size)
381	        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
382	    if requested > control.ledger.available() {
383	        return Err(limit(LimitKind::ReservedBytes, offset));
384	    }
385	    let mut values = Vec::new();
386	    values.try_reserve_exact(target).map_err(|_| oom(offset))?;
387	    let new_bytes = values
388	        .capacity()
389	        .checked_mul(size)
390	        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
391	    let old_bytes = old
392	        .capacity()
393	        .checked_mul(size)
394	        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
395	    let lease = control.ledger.admit(AllocationTag::None, new_bytes)?;
396	    Ok(Some(Replacement {
397	        values,
398	        lease,
399	        old_bytes,
400	        new_bytes,
401	    }))
402	}
403	
404	fn reconcile<T>(buffer: &Replacement<T>, control: &mut PaintControl<'_>) -> Result<()> {
405	    if buffer.old_bytes == 0 {
406	        return Ok(());
407	    }
408	    control.ledger.release(buffer.lease)?;
409	    let _job_lease = control
410	        .ledger
411	        .admit(AllocationTag::None, buffer.new_bytes - buffer.old_bytes)?;
412	    Ok(())
413	}

