276	struct StopAt {
277	    remaining: usize,
278	    polls: usize,
279	}
280	impl StopAt {
281	    fn poll(&mut self) -> std::result::Result<(), Stop> {
282	        self.polls += 1;
283	        if self.remaining == 0 {
284	            Err(Stop::Canceled)
285	        } else {
286	            self.remaining -= 1;
287	            Ok(())
288	        }
289	    }
290	}
291	impl WorkControl for StopAt {
292	    fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> {
293	        self.poll()
294	    }
295	    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
296	        self.poll()
297	    }
298	}
