145	    if raw.len() < 7 || !raw.starts_with(b"url(#") || raw.last() != Some(&b')') {
146	        return Err(unsupported(value.offset));
147	    }
148	    let id = XmlSpan {
149	        offset: value.offset + 5,
150	        length: value.length - 6,
151	    };
152	    if id.length == 0 {
153	        return Err(unsupported(value.offset));
154	    }
155	    let target = shared
156	        .find_reference(id, control)
157	        .map_err(|error| remap(error, value.offset))?
158	        .ok_or_else(|| unsupported(value.offset))?;
159	    let token = shared
160	        .tokens()
161	        .get(target.0)
162	        .ok_or_else(|| invalid(value.offset))?;
163	    if token.prefix.length != 0 {
164	        return Err(unsupported(value.offset));
165	    }
166	    if eq(source, token.local_name, b"linearGradient")
167	        || eq(source, token.local_name, b"radialGradient")
168	    {
169	        Ok(PaintReference::Gradient(target))
170	    } else if eq(source, token.local_name, b"pattern") {
171	        Ok(PaintReference::Pattern(target))
172	    } else {
173	        Err(unsupported(value.offset))
174	    }
